insert into public.theories (id, question_id, legacy_author_key, identity_mode, thesis, paragraphs, change_mind, status, dmz_pick, starter, needs_review, legacy_url, created_at, published_at) values
  ('l7123', 'what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-conscious', 'cnscsns', 'name', null, array['The human being suffers and has always suffered at the hands of the human mind. The sense of imprisonment, confusion and estrangement experienced regularly by most humans daily naturally takes a toll. We seek to escape the clutches of the mind, even if just temporarily. We find such refuge through many means – from excessive eating, exercise, watching TV and using our phones, to consuming alcohol and drugs. All of these examples are similar in that they are all mind-altering. They take us out of a certain state of mind and place us into another – almost immediately. Venturing into the realm of psychedelics, we see a perhaps different type of mind-altering substance. An intention less of distraction and escapism, and more geared towards exploration and expansion. Humans have been experimenting all types of mind-altering substances for as long as we have been around, and continue to do so today. Such a trend is an indelible quality of human nature and human evolution.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-consciousness/what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-consciousness/', '2021-02-20T12:00:00Z', '2021-02-20T12:00:00Z'),
  ('l7120', 'what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-conscious', 'gareth-c', 'name', null, array['Among scientists, there are tentative signs of a psychedelics renaissance. After decades of stigma, impressive research is showing the power of these substances to help sufferers of depression and addiction, or to comfort patients with a terminal cancer diagnosis, struggling to face their own end. This is the fascinating territory that the journalist Michael Pollan explores with his new book, “How to Change Your Mind.” Pollan dives into brain science, the history of psychedelics (and our tortured attitudes towards them) but his larger subject is the nature of human consciousness. Eventually Pollan decides to try psychedelics himself — and documents, beautifully, a number meaningful experiences and the way his own mind has changed. He answered questions from Mind Matters editor Gareth Cook.', 'How did you get interested in writing about this topic, after all of your work on food?', 'It’s true I’m best known for my books about food and agriculture, but that work grew out of a deeper fascination with the human engagement with the natural world, and the species we co-evolved with, a fascination I explored in earlier books like The Botany of Desire and Second Nature. Food and beauty are two of the human desires other species have evolved to gratify, but there are other, more mysterious desires, and the human drive to change consciousness, whether mildly and routinely with plant drugs such as caffeine, or more dramatically with psychoactive mushrooms, has always fascinated me. Why do we want to do this potentially risky thing, and why did plants and fungi evolve these remarkable chemicals that affect us in this way? What do these experiences do for us, as individuals or as a society? Psychedelics are the most extreme case of this curious phenomenon, and they have been a central part of human societies for thousands of years. I wanted to find out why.ADVERTISEMENT', 'And then I began hearing about a renaissance of research into psychedelics by scientists hoping to treat cancer patients suffering from “existential distress,” addicts, people struggling with depression and so-called “healthy normals.” These researchers had found that psilocybin, the psychoactive compound in magic mushrooms, could reliably occasion a “mystical experience” in people that they deemed one of the two or three most significant experiences in their lives—comparable to the birth of a child or death of a parent. The experience had changed them in lasting ways. This was something I needed to explore. I wasn’t sure I had ever had a spiritual experience. Would one happen to me? Was there some dimension of existence or consciousness I was missing out on? Was it really possibly to change one’s mind as an adult? My journalistic curiosity soon morphed into a personal quest to explore some of the uncharted territory of both the mind and my mind.', 'Can you explain what the “default mode network” is, and how it figures in your story?', 'One of the most interesting early findings of recent psychedelic research is that activity in the “default mode network” falls off sharply during the psychedelic experience. This network is a critical hub in the brain that links parts of the cerebral cortex to deeper and older structures involved in memory and emotion. The DMN appears to be involved in a range of “metacognitive” functions such as a self-reflection; mental time travel; theory of mind (the ability to imagine the mental states of other people) and the creation of the so-called “autobiographical self”—the process of weaving what happens to us into the narrative of who we are, thereby giving us a sense of a self that endures over time. (Curiously, fMRI’s of the brains of experienced meditators shows a pattern of activity, or quieting of activity, very similar to that of people who have been given psilocybin.) When the default mode network is taken offline by a psychedelic, not only do we experience a loss of the sense of having a self, but myriad new connections among other brain regions and networks spring up, connections that may manifest in mental experience as hallucination (when, say, your emotion centers talk directly to your visual cortex), synesthesia (as when you can see sound or hear flavors) or, possibly, fresh perspectives and metaphors. Disturbing a complex system is a great way to force it to reveal its secrets—think of a particle accelerator—and psychedelics allows us to do that to normal ego-centered consciousness.', 'You tried psychedelic drugs as a part of your work on this book, and I wonder which of those experiences most changed you?', 'After interviewing dozens of volunteers who had had guided psychedelic trips I became so curious that I decided to have one (actually several) myself. I think the most transformative of these was a guided trip on psilocybin, during which I experienced the complete dissolution of my ego—I could see the entity formerly understood as me “out there” spread over the landscape like a coat of paint. Yet there was still some recording “I” taking in the scene, a sort of disembodied, dispassionate awareness. Though temporary, that perspective was transformative. It suggested to me that I wasn’t necessarily identical to my ego, that there was potentially another ground on which to plant my feet. In subtle ways this has changed my relationship to my ego, which I no longer regard as identical to me, odd as that sounds, but as a kind of useful though sometimes neurotic and annoying character who occasionally needs to be put in his place. Sometimes when I’m reacting to an event or comment I can catch myself before the usual defenses leap into action, because I can see what he’s up to and why. This is the sort of perspective you can occasionally develop with years of meditation or psychoanalysis; psilocybin gave it to me in an afternoon.ADVERTISEMENT', 'What do you wish the general public understood about psychedelic drugs and their potential?', 'The image of psychedelics in the public mind has been substantially shaped by the Sixties counterculture and Timothy Leary, but that is just one brief chapter in a much longer and more interesting history reaching back thousands of years, one in which these drugs were the subject of serious research and, long before that, carefully regulated use, usually in a ritual context. These remarkable molecules have the potential—and I stress “potential,” because much more research needs to be done—to relieve the suffering of millions of people struggling with depression, anxiety, obsession, addiction and the fear of death. Many of the researchers involved believe we could be on the verge of a revolution in mental health care, which is a segment of medicine that right now has very little to offer and is dire need of some new thinking and new tools. The drugs can be used carelessly, as they often were in the sixties, but in the proper hands, they can heal and illuminate the mind.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-consciousness/qotw0221-3/', '2021-02-20T12:00:00Z', '2021-02-20T12:00:00Z'),
  ('l7115', 'what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-conscious', 'beth-d', 'name', null, array['It’s easy to explain the appeal of drugs like heroin and cocaine, which directly stimulate the brain’s reward centres. What’s less easy to explain is the appeal of psychedelic drugs such as LSD and psilocybin that produce altered states of consciousness. After all, there’s no obvious reason why unusual patterns of thought and perception – typically, the symptoms of poisoning or illness – should be attractive. And yet, people not only pay money for these experiences, they even run the risk of being imprisoned or worse for doing so. Why is this?', 'One answer is that these drugs provide short cuts to religious and transcendental experiences that played an important role in human evolution. The logic behind this idea becomes clearer when we look at how human culture was shaped by religious ideas.', 'For some time, anthropologists have argued that religious people are more cooperative than nonreligious ones. For small groups, the effect of religion is negligible or even negative. However, as group size increases, it seems that religion plays an increasingly important role in creating bonds between strangers. In fact, some scholarship suggests that the emergence of the first city states in the Middle East nearly 12,000 years ago was made possible by belief in “Big Gods”, who supposedly oversaw all human action and guided human affairs.', 'Why does religion make people more cooperative? On the one hand, the belief that a morally concerned, invisible agent is always watching you makes you less likely to break rules for personal gain. This effect is quite powerful. Research shows that even something as trivial as a picture of a pair of eyes on an honesty box is enough to make people pay three times as muchfor their drinks.', 'About us', 'Ruby slippers LSD sheet. William Rafti, CC BY', 'On the other hand, religion connects people with a reality larger than themselves. This might be the social group that they belong to, it might be life after death, or it might even be the cosmos as a whole. The connection is important because it makes people more willing to cooperate when the results of doing so are not immediately beneficial. If I believe myself to be at one with my tribe, my church or the universe itself, it’s easier to accept others getting the benefits of my hard work.', 'It is probably this second aspect to religious cooperation than explains the appeal of psychedelic drugs. By simulating the effects of religious transcendence, they mimic states of mind that played an evolutionarily valuable role in making human cooperation possible – and with it, greater numbers of surviving descendants. This does not mean that humans evolved to take psychedelic drugs. But it does mean that psychedelic drug usecan be explained in evolutionary terms as a “hack” that enables transcendent states to be reached quickly.', 'Legal systems can’t change human nature', 'If this story is true, what are its implications? One is that psychedelic drug use is no different, in principle, to practices like chanting, fasting, praying and meditating that religions typically use to bring about altered states of consciousness. Purists may object to drug taking because it lacks the spiritual discipline involved in such procedures. This is true, but one could just as easily argue that buying a car lacks the practical discipline of building an internal combustion engine from scratch. And in any event, there are many religions that use psychoactive substances in their ceremonies.', 'A second implication is that psychedelic drugs may play a positive role in improving mental outlook. Already, there are promising results concerning the effects of psychedelics on the depressed and the terminally ill. Though this is no guarantee that such results will hold good for everyone, it gives grounds for thinking that there is a portion of the population for whom psychedelic drugs can produce valuable effects.', 'Banning psychedelic drugs is likely to be counterproductive. Just as banning sexual activity does not stop sexual desire, outlawing psychedelic drugs does nothing to change the innate need for transcendent experiences. A sensible legal approach would create a framework that allows people to use psychedelic drugs while minimising the harms. The fact is, no legal system yet has succeeded in changing human nature, and there is no reason to think that that prohibiting psychedelic drugs will be any different.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-consciousness/qotw0221-2/', '2021-02-20T12:00:00Z', '2021-02-20T12:00:00Z'),
  ('l7112', 'what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-conscious', 'sarah-s', 'name', null, array['IMAGINE HOMO ERECTUS, A NOW-EXTINCT SPECIES OF HOMINIDS THAT STOOD UPRIGHT AND BECAME THE FIRST OF OUR ANCESTORS TO MOVE BEYOND A SINGLE CONTINENT. AROUND TWO MILLION YEARS AGO, THESE HOMINIDS, SOME OF WHOM EVENTUALLY EVOLVED INTO HOMO SAPIENS, BEGAN TO EXPAND THEIR RANGE BEYOND AFRICA, MOVING INTO ASIA AND EUROPE. ALONG THE WAY, THEY TRACKED ANIMALS, ENCOUNTERED DUNG, AND DISCOVERED NEW PLANTS. But that’s just the version of our origin story that happens to be widely accepted by scientists.', 'A more radical interpretation of these events involves the same animals, dung, and plants but also includes psychedelic drugs. In 1992, ethnobotanist and psychedelics advocate Terence McKenna argued in the book Food of the Gods that what enabled Homo erectus to evolve into Homo sapiens was its encounter with magic mushrooms and psilocybin, the psychedelic compound within them, on that evolutionary journey. He called this the Stoned Ape Hypothesis.', 'McKenna posited that psilocybin caused the primitive brain’s information-processing capabilities to rapidly reorganize, which in turn kick-started the rapid evolution of cognitionthat led to the early art, language, and technology written in Homo sapiens’ archeological record. As early humans, he said we “ate our way to higher consciousness” by consuming these mushrooms, which, he hypothesized, grew out of animal manure. Psilocybin, he said, brought us “out of the animal mind and into the world of articulated speech and imagination.”', 'As human cultural evolution led to the domestication of wild cattle, humans began to spend a lot more time around cattle dung, McKenna explained. And, because psilocybin mushrooms commonly grow in cow droppings, “the human-mushroom interspecies codependency was enhanced and deepened. It was at this time that religious ritual, calendar making, and natural magic came into their own.”', 'McKenna, who died in 2000, passionately believed in his hypothesis, but it was never seriously considered by the scientific community during his lifetime. Dismissed as excessively speculative, McKenna’s hypothesis now only pops up occasionally in online message boards and Reddit pages dedicated to psychedelics.', 'However, a talk in April at Psychedelic Science 2017, a scientific conference on psychedelics attended by researchers, therapists, and artists who believe in the therapeutic potential of these drugs, renewed interest in the theory. There, Paul Stamets, D.Sc., a noted psilocybin mycologist, advocated for the Stoned Ape Hypothesis in his talk, “Psilocybin Mushrooms and the Mycology of Consciousness.”', '“I present this to you because I want to bring back the concept of the Stoned Ape Hypothesis,” Stamets said to the crowd. “What is really important for you to understand is that there was a sudden doubling of the human brain 200,000 years ago. From an evolutionary point of view, that’s an extraordinary expansion. And there is no explanation for this sudden increase in the human brain.”', 'The “doubling” he talked about refers to the sudden growth in the size of the human brain, and he’s right: The details are still up for debate. Some anthropologists believe that the brain size of Homo erectus doubled between 2 million and 700,000 years ago. Meanwhile, it’s estimated that the brain volume in Homo sapiens grew three times larger between 500,000 and 100,000 years ago.', 'Laying out the tenets of the Stoned Ape hypothesis that McKenna and his brother Dennis shaped, Stamets painted a portrait of primates descending from African canopies, traveling across the savannahs, and coming across “the largest psilocybin mushroom in the world growing bodaciously out of dung of the animals.”', '“I suggest to you that Dennis and Terence were right on,” Stamets announced while acknowledging that the hypothesis was perhaps still unprovable. “I want you or anyone listening, or seeing this, to suspend your disbelief … I think this is a very, very plausible hypothesis for the sudden evolution of Homo sapiens from our primate relatives.”', 'The crowd broke out into wild applause.', 'Terence McKenna advocated for the Stoned Ape hypothesis.Wikimedia Commons', 'Is it finally time to take the Stoned Ape hypothesis seriously? Doing so requires integrating our advancements in scientific research on psilocybin, recent archeological discoveries, and our murky understanding of human consciousness and fitting these into our current understanding of human evolution. We can start with the common threads between McKenna’s view of the development of consciousness and other, more mainstream, theories, including the commonly accepted view that it emerged over thousands of years and that language played a central part in its evolution.', '“I think that, like anything, there’s possibly some truth in what he [McKenna] says,” paleontologist Martin Lockley, Ph.D., tells Inverse. Lockley, the author of a book called How Humanity Came Into Being, has one major issue with McKenna’s reasoning: Believing in the Stoned Ape hypothesis, which posits that our ancestors got high and consequently became conscious, also means agreeing that there was a singular cause for the emergence of consciousness. Most scientists, Lockley included, think it was much less straightforward than that.', 'Consciousness, after all, is a very complex thing that we are only beginning to understand. Anthropologists generally accept that it’s a function of the human mind involved with receiving and processing information that evolved over millennia of natural selection. A state of consciousness comprises an awareness of multiple qualitative experiences: sensations and feelings, the nuances of sensory qualities, and cognitive processes, like evaluative thinking and memory. In 2016, scientists pinpointed where all of this lives in the brain, discovering a physical link between the brain regions associated with arousal and awareness.', 'McKenna’s theory chalks up the entirety of this complicated phenomenon to a single spark; to him, psilocybin mushrooms were the “evolutionary catalyst” that sparked consciousness by prompting early humans to engage in experiences like sex, community bonding, and spirituality. Most scientists would argue that McKenna’s explanation is excessively, and perhaps naively, simplistic.', 'And yet, they’re equally stumped when asked to answer the question at the root of the debate over the Stoned Ape hypothesis and consciousness research in general: How did consciousness evolve? If it wasn’t psychedelic mushrooms that started the process, then what did? Michael Graziano, Ph.D., a professor of psychology and neuroscience at Princeton University who studies consciousness, had not heard of the Stoned Ape theory but concurs that the evolution of human consciousness is somehow linked to the formation of communities. In his own theory, he argues that brains had to develop the ability to understand subjective experiences to serve social needs. Since it was evolutionarily beneficial to be socially intelligent, he says, it’s reasonable to believe that consciousness evolved as a survival tactic.', '“It is possible that consciousness emerged partly to monitor, understand, and predict other creatures, and then we turned the same skill inward, monitoring and modeling ourselves,” Graziano tells Inverse. “Or it could be that consciousness emerged much earlier, when basic attentional focus first emerged, and that it is related to the ability to focus the brain’s resources on a limited number of signals. That would put it very early in evolution, perhaps half a billion years ago.”', 'Psilocybin mushrooms, or “magic mushrooms,” in MexicoWikimedia Commons', 'Likewise, the theories of anthropologist Ian Tattersall, Ph.D., have nothing to do with psychedelic drugs but share the Stoned Ape’s emphasis on socialization. In his 2004 paper“What happened in the origin of human consciousness?” Tattersall, a researcher at the American Museum of Natural History, argued that self-awareness — and thus consciousness — was born as early man learned to consider itself apart from nature and grew capable of evaluating and expressing the thoughts within its mind. Language developed shortly after, followed by modern human cognition.', 'Where Tattersall remains stumped — and where McKenna’s theory offers some explanation — is in trying to figure out when that crucial transition took place.', '“Where did modern human cognition emerge?” Tattersall writes. “Almost certainly in Africa, like modern human anatomy. For it is in this continent that we find the first glimmerings of ‘modern behaviors’ … But the moment of transformation still eludes us and may well do so almost indefinitely.”', 'McKenna might have argued that psilocybin-containing mushrooms caused this “moment of transformation.” But even experts on ancient drug users think it’s unlikely that a single factor caused such a radical change, despite it being entirely reasonable to think that early hominids munched on magic mushrooms as they made their way through Africa.', '“Human evolution is a tremendously intricate process in which several factors have played their part,” archeologist Elisa Guerra-Doce, Ph.D., tells Inverse. Guerra-Doce’s research on the use of drug plants in prehistoric times has detailed how early humans used mind-altering drugs for ritual and spiritual purposes. But despite the fact that she’s encountered remnants of opium poppy in the teeth of Neolithic specimens, ancient charred cannabis seeds, and even abstract drawings of the use of hallucinogenic mushrooms on cave walls in the Italian Alps, she is not on board with the Stoned Ape hypothesis.', '“From my point of view, McKenna’s hypothesis is too simplistic and lacks direct evidence to support it — that is, any evidence of consumption of hallucinogenic mushrooms by the earliest Homo sapiens,” she says, pointing out that he got some of his basic facts wrong. “He points to the Algerian paintings of Tassili-n-Ajjer, which include some depictions of mushrooms, but we must bear in mind that these paintings date back to the Neolithic.”', 'If the science behind McKenna’s hypothesis is unstable, what worth does it have in the search for the origin of human consciousness?', 'A scan of a brain on psilocybin, which decreases activity in the medial prefrontal cortex.Imperial College', 'At its best, the Stoned Ape hypothesis is, as Stamets described it, an “unprovable hypothesis” that fits some – but not nearly all – of the knowledge we have about the evolution of consciousness. At its worst, it’s a gross oversimplification of the multitude of factors that may have jump-started modern human cognition and consciousness. However, McKenna deserves credit for sparking an idea in the 1990s that scientists have only recently been able to prove: Psilocybin does alter consciousness and can trigger physical changes in the brain.', 'In recent years, drug researchers have determined that psilocybin induces a state of “unconstrained cognition,” triggering a pronounced surge in activity in the primitive brain network, the region associated with emotional reactions. On psilocybin, the parts of the brain linked to emotions and memory become more coordinated, creating brain activity patterns resembling those of people who are asleep and dreaming. At the same time, the region that controls higher-level thinking and is linked to a sense of self becomes disorganized, which is why some people who take psilocybin feel a loss of “ego,” leading them to feel more a part of the world than they do their own bodies.', 'Regardless of the holes that have been pointed out in McKenna’s scientific logic, Amanda Feilding, founder and director of the Beckley Foundation, a leading psychedelic research think tank, tells Inverse that we must see past McKenna’s errors and consider his greatest insight: that the story of humankind is inseparable from our fascination with psychedelic drugs. Even if early man encountered psychoactive substances closer to the Neolithic period, she says, the experience of entering an altered state of consciousness likely changed human society for the better.', '“The imagery that comes with the psychedelic experience is a theme that runs through ancient art, so I’m sure that psychedelic experience and other techniques, like dancing and music, were used by our early ancestors to enhance consciousness, which then facilitated spirituality, art, and medicine,” she says.', 'The Stoned Ape hypothesis may now be lost to the annals of fringe science, but some remnant of its legacy remains. Now that scientists better understand the way psilocybin physically affects the brain, they can seriously investigate its potential to treat disorders like substance abuse, anxiety, and depression. If that happens — and it looks like it will — psilocybin will become a part of mainstream culture as an agent of positive change. And isn’t that ultimately what McKenna was advocating for?', 'Maybe we’ll never know how magic mushrooms helped early humans. But there’s no doubt they’ll be contributing to the wellness of modern humans as we continue down our strange evolutionary path.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-consciousness/qotw0221/', '2021-02-20T12:00:00Z', '2021-02-20T12:00:00Z'),
  ('l7153', 'what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-conscious', 'martin-b', 'name', null, array['Psychedelics are technology, and they can show us what we really are. Are we really that evolution? Or there’s more? It’s a reflexion, the most pure one, a portal that opens a door to a garden full of everything. New species of animal and trees, the sun baths the strange and beautiful flowers with exquisite smell and shape. That’s what we are, and if that’s our evolution then it’s ok to think that psychedelics are important because they show you the path, they put it in front of your eyes and makes you look without caring the consequences and perhaps that’s what evolution is about.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-effect-do-mind-altering-substances-have-on-the-evolution-of-human-consciousness/what-is-the-effect-of-mind-altering-substances-on-the-evolution-of-human-consciousness/', '2021-02-28T12:00:00Z', '2021-02-28T12:00:00Z'),
  ('l7151', 'what-is-the-glue-that-binds-everything-together', 'ruby', 'name', null, array['Is it cliche to say ‘LOVE’? Perhaps. But it is the truth – Love is the glue that binds everything together. Love is gravity. Love is desire. Love is the connective force. As the Universe explodes and expands, it is this force of love that holds it together. As human beings, our unique experiences of love is our vessel into understanding the Universe – the basic glue, the basic pattern, and the basic purpose of it all. We must not proclaim to know beyond our means, but rather aspire to connect, to listen, and ultimately to allow the Universe’s basic truths to actualize through us, via the force of love that we are capable of experiencing.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-glue-that-binds-everything-together/what-is-the-glue-that-binds-everything-together/', '2021-02-28T12:00:00Z', '2021-02-28T12:00:00Z'),
  ('l7148', 'what-is-the-glue-that-binds-everything-together', 'alan-s', 'name', null, array['The ‘glue.’ What a simple, clear, and critically important concept. “Glue” is what holds things together. With an object, it’s literally the sticky substance that binds one piece to another. In our lives, on the other hand, the “glue” is the stuff that binds together our families, our friendships, and our intimate relationships. It’s the energetic connection that holds people together in companies, organizations, societies, and countries. The question is: What is it?', 'The “glue” that initially brings people together might be a belief in what they are doing together. Or it might be a set of values, or a shared experience. Or maybe it’s a strong attraction or admiration that they can’t explain. It’s just there.', 'However, as time goes on, the project, mission, values, or attraction alone will not be enough. The glue that comes out of a tube and holds an object together eventually dries out and needs to be renewed. And so it is in our relationships, in our families, in our communities, and in our companies. When we don’t pay attention to the “glue” – when we don’t take care of what holds us together – over time, it will begin to dry out and crack. And things will start to break apart.', 'I often define Transformational Presence with the metaphor of “tending the garden.” It’s about taking care of the culture or environment within which we live and work.', 'More recently, I’ve described it as “taking care of the Ma.” Ma is a Japanese concept referring to the energetic space within a situation, a project, a relationship, a group or a room. It’s about the quality of the energy that is in the space between people, between people and a situation, between one situation and another, between one group and another group, between us and the environment, or between cultures. Ma refers to the quality of energy of any space, physical or non-physical. And that includes the quality of energy within ourselves.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-glue-that-binds-everything-together/qotw0228-3/', '2021-02-28T12:00:00Z', '2021-02-28T12:00:00Z'),
  ('l7145', 'what-is-the-glue-that-binds-everything-together', 'robert-k', 'name', null, array['You do not know what stuff is, you who hold it in your hands. Atoms? Yes, stuff is made of atoms. And every atom is a nucleus orbited by electrons. Every nucleus is built of protons. Every proton is – but there you reach the end of the line. Inside the proton lies the deep, unsettling truth: Stuff is made of nothing, or almost nothing, held together by glue, lots of glue. Physicists first began to suspect this in 1973. Lately it has been proved by experiment.', 'Frank Wilczek was a 21-year-old graduate student at Princeton University when hehelped develop this theory of the proton in 1973. He didn’t really understand it himself at first; he was just following where the math led him. “We did the calculations, but we didn’t have a simple intuitive understanding,” Wilczek says. “The physical picture came later.” That picture took a while even for physicists to absorb, because it really isn’t simple. Even today, if you ask a physicist to describe a proton, you’ll first get a cartoon version—the one that says a proton is made simply of three smaller particles called quarks. That description is not exactly false—it’s just low resolution. It’s true the way a picture of Times Square from 30,000 feet away is true. The close-up reality, the one Wilczek and his colleagues got a glimpse of long ago, is far more madding and strange.blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30', 'A proton is made of three quarks, yes, but the quarks are infinitesimal—just 2 percent or so of the proton’s total mass. They’re rattling around at near light speed inside the proton, but they’re imprisoned in flickering clouds of other particles—other quarks, which materialize briefly and then vanish and, above all, gluons, which transmit the force that binds the quarks together. Gluons are massless and evanescent, but they carry most of the proton’s energy. That is why it is more accurate to say protons are made of gluons rather than quarks. Protons are little blobs of glue—but even that picture conveys something too static and substantial. All is flux and crackling energy inside a proton; it is like an unending lightning storm in a bottle, a bottle less than .1 trillionth of an inch in diameter. “It’s a very rich, dynamic structure,” says Wilczek. “And it’s very pleasing that we have a theory that can reproduce it.”', 'Especially if you happen to be one of the guys who invented the theory, and if, more than two decades later, that theory is actually being verified by experiment. At a particle accelerator called HERA in Hamburg, Germany, physicists have been firing electrons into protons for the past eight years, showing just how insubstantial the quarks are inside. Meanwhile, other accelerator experiments may soon reveal how the universe assembled all its protons in the first place. In February, physicists at CERN, the European Laboratory for Particle Physics outside Geneva, announced “compelling evidence” that they had succeeded in melting large numbers of protons, creating for an instant the kind of quark-gluon plasma that last existed a microsecond after the Big Bang. All the protons around now congealed from that soup. At Brookhaven National Laboratory on Long Island in New York, a new and more powerful accelerator is getting set to cook quark-gluon soup on a daily basis this summer. By next year physicists may have a much better idea of what the universe was like when it was a billion times hotter than the surface of the sun, and quarks and gluons—not yet trapped inside protons, inside nuclei, inside atoms, inside us—could play freely in the quantum fields.', 'Quantum chromodynamics, or QCD, the theory that Wilczek and his colleagues invented, is a type of quantum field theory, and quantum field theory for beginners goes something like this. First, E=mc2, as Einstein discovered. That is, energy can be converted into mass and vice versa. Second, empty space is not empty: What we call a vacuum is actually seething with all kinds of energy fields, and the energy is constantly manifesting itself as “virtual” particles that pop into existence and then disappear again in something less than a trillionth of a nanosecond. “It wouldn’t be very useful to us to see this structure of the vacuum,” says Wilczek, who is now a professor at the Institute for Advanced Study at Princeton, where he lives in Einstein’s old house. “It wouldn’t help us avoid saber-toothed tigers or raise our children, so evolution has taught us to ignore it. But it’s there.”', 'Third (and last in our field-theory primer), when two subatomic particles exert a force on each other, they are interacting via one of those energy fields, which they themselves help to create. Specifically, they are exchanging one of those virtual particles—the quantum of the quantum field. An electron, for instance, has an electric charge of -1, and that charge generates an electric field. If the electron is moving, as it always is—spinning on its axis and orbiting the atomic nucleus—it generates a magnetic field as well; all magnetic fields are ultimately created by moving electric charges. When two charged particles interact—when, say, an electron is scattered off a proton in HERA—they exchange a virtual photon, the quantum of the electromagnetic field. The theory that describes such interactions, invented by Richard Feynman, among others, is called quantum electrodynamics, or QED.', 'In QED each individual electron is surrounded by a cloud of short-lived virtual particles—photons, but also other electrons paired with positrons, their positively charged antimatter twins. Those swarming particle pairs form a screen that partially cancels the electron field—at least as seen from outside the screen. From inside the screen, on the other hand, the field seems stronger than you might expect, like a bare lightbulb once a lamp shade has been removed. “OK, so that’s screening, and that’s pretty easy to understand,” says Wilczek. “What happens in QCD, inside the proton, is just the opposite: It’s antiscreening. It was a surprise even to us, so it can’t be too simple. But we’ve come to understand it in more elementary terms over the years.” blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30', 'The early 1970s, when Wilczek did his pioneering work, was a heady time for particle physicists. Their air is somewhat different from what the rest of us breathe, and QCD was in it. A few years earlier, researchers at the Stanford Linear Accelerator Center had for the first time accelerated electrons to energies high enough to penetrate protons. The electrons didn’t seem to be plunging into mush; they seemed to bounce off pointlike nuggets within the protons. Quarks, which had been postulated in 1964 as purely mathematical entities, began to seem as if they might really exist inside protons—and the question of how the whole thing was held together became urgent and exciting. While Wilczek and his adviser, David Gross, were discovering the answer at Princeton, another graduate student named David Politzer was discovering it independently at Harvard. Gross was the old man of the trio at 31. “We were lucky to have been young then,” he wrote later, “when we could stroll along the newly opened beaches and pick up the many beautiful shells that experiment had revealed.”', 'One shell was stranger than the rest. The Stanford experiments had seemed to show that the force between quarks—known as the strong force—actually got weaker as the quarks got closer together. That was very strange. The forces we encounter on a daily basis, electromagnetism and gravity, act in just the opposite way: They are stronger at short distances from their source and weaker at long ones. That is the intuitive way; that is how things should be. Otherwise, for instance, magnets would fly off your refrigerator to cling to the distant alluring stove—except that from a distance the fridge would start to look good to them again. And yet, weak as the strong force was at very short distances, it was strong enough at longer ones to frustrate physicists who had tried hard and failed to pull a quark out of a proton. No one had managed to observe one in isolation.', 'Wilczek and Gross went looking for a quantum field theory that could explain such a force. Actually Gross expected them to fail; he wanted to prove that field theory was a dead end. But one kind of mathematical formalism, called non-Abelian gauge theory, had not yet been tried. Wilczek spent half a year filling a notebook with calculations of how particles would interact through a non-Abelian quantum field. At the end he had a force that got stronger at close quarters, as a good force should, as Gross expected—but unlike what had been measured at Stanford. Wilczek checked the lengthy calculations over and over again. Then Gross spotted a single plus sign in the field equation that should have been a minus. That sign change changed everything: QCD was born.', 'Inside a proton, according to QCD, the quarks are “asymptotically free,” as the Stanford results suggested, meaning they move almost as if there were no force between them at all. But the freedom is an illusion: A quark can never escape its partners. As the distance between them increases, so does the force, and so a wayward quark is inevitably reined in, like a bungee jumper. That’s why no one ever has or ever will see a lone quark, which, when you think about it, is deeply weird. “The proton has parts, but it can’t be taken apart,” says Alvaro de Rújula, a theoretical physicist at CERN. “You can hold an electron in your hand. You can’t hold a quark or a gluon in your hand.”', 'The weirdness comes from the gluons. Quantum chromodynamics, the force that holds protons together, is modeled closely on quantum electrodynamics, the force that holds atoms together—but the gluons change screening to antiscreening, intuitive to bizarre. In quantum chromodynamics, quarks carry a new kind of charge, called color—which has nothing to do with ordinary color—and those charges generate a color field (hence the name chromodynamics). The quantum of the field, and the transmitter of the strong force, is the gluon. Like the photon that transmits the electromagnetic force, a gluon is massless. But unlike the photon, a gluon is charged. It generates its own color field, exerts its own strong force, and ineracts with other gluons. It leads a rich life.blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30', 'The color field, like the electromagnetic one, can be thought of as having two components—call them color electric and color magnetic. A fast-moving color charge—gluons move at light speed—generates a strong color-magnetic field. Gluons are thus like little dipole magnets. The gluons that surround a quark align themselves parallel to its color field, as magnets would, and so instead of weakening it, as virtual particles do an electron’s field, they strengthen it. They antiscreen the quark, amplifying its field. Here the lamp analogy no longer works—the quark is a dim bulb that somehow becomes brighter outside the shade.', 'That’s what holds a proton together, and that’s what gives it a bizarre internal structure. If one quark manages to get inside another’s gluon cloud, it feels only a feeble attraction. But the farther away it goes, the more it feels the added pull of gluons—gluons emitted by the quarks, gluons emitted by other gluons, gluons that materialize into virtual quark-antiquark pairs, which exchange more gluons. “The quarks trigger the whole thing, but once it starts, it’s a very powerful process, because the gluons interact,” says Wilczek. “It’s a sort of runaway process.”', 'In 1974, De Rújula, Politzer, Wilczek, and a few other physicists proposed this gluonization of the proton and suggested how it might one day be measured. Two decades later, scientists at HERA started doing just that. HERA is a ring-shaped accelerator, nearly four miles around, in which electrons doing 47,000 laps a second are smashed into protons going the other way. The greater the energy of the collision, the deeper an electron can bore into a proton before being deflected. By measuring how the electron is deflected in millions of collisions, physicists can collect information on the internal components that are doing the deflecting. It’s like taking a picture of the inside of a proton, Wilczek says, pixel by pixel—and the results fit the proposal he and his colleagues made decades ago.', '“It’s only at the crudest level that a proton is made of three quarks,” Wilczek says. “When you look close and get inside these clouds and start seeing the basic structure, you see that it’s mostly glue.”', 'Which makes all the more interesting the question of how the universe ever managed to design such a thing.blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30', 'To visit a particle-physics laboratory is to be struck by a contrast in scale—between the smallness of the objects being studied and the hugeness of the resources—people, machinery, computing power, electric power, space, money—that are being devoted to it. (If that infrastructure seems a high price to pay for information on the origin of the universe, consider that the Web—designed to help scientists communicate enormous data files—is a CERN brainchild.) CERN consumes almost as much electricity as the city of Geneva, its neighbor. CERN’s biggest accelerator, the Large Electron-Positron collider, occupies a circular tunnel 17 miles around. In the coming years it will be dismantled and replaced by an even more powerful accelerator, the Large Hadron Collider, which will re-create the energy that existed a trillionth of a second after the Big Bang. (Hadrons are nuclear particles, like protons, that are made of quarks and gluons.) To make a quark-gluon plasma, you don’t need to go that far back in time—the first microsecond will do—so you need a less powerful accelerator.', 'Still, the Super Proton Synchrotron at CERN is more than four miles around. It’s housed in a tunnel that lies 300 feet underground, and in that tunnel, inside an aluminum tube just a few inches wide, lead nuclei are accelerated by magnets to 99.9 percent of the speed of light. They are then guided up to the surface and into an immense, factorylike hall, 300 yards long. The aluminum tube forks into different detectors, where the lead nuclei—each one consisting of 208 protons and neutrons, the electrically neutral twins of protons—smash into a piece of lead foil that is just a few hundred micrometers thick.', 'What happens next, in theory, is simple: The collision creates a fireball intense enough to melt the protons and neutrons. The quarks and gluons circulate freely, as they do deep inside a proton, but now over a region that is many protons wide, forming a quark-gluon plasma. “If you run the movie of the Big Bang backward, it gets denser and denser, hotter and hotter,” says Reinhard Stock of the University of Frankfurt, who helped design one of the CERN detectors, “and we know that all bound structures break up when their energy density exceeds their binding energy.” Quantum chromodynamics demands that a quark-gluon plasma exists at a certain energy density, “but you have to prove that it exists,” says Stock. “And that’s why we have been here for the last 15 years.”', 'The problem is that the laboratory fireball expands rapidly and cools rapidly, just as the primordial one must have done. The plasma survives for only 10–22 of a second before the quarks and gluons condense again into protons and other hadrons. What physicists actually detect is a spray of thousands of such particles coming out the back of the lead foil. In Stock’s detector, the particles then fly through a room-sized box of argon gas, knocking electrons off argon atoms. Counters record the electrons, and computers reconstruct the particle tracks, which reveal their identity. Once physicists have analyzed the data deluge—each collision yields 10 megabytes of data, and Stock and his colleagues have recorded millions of collisions—they may learn something about the plasma-producing fireball.', 'Over the past few years, Stock’s detectors and others at CERN have confirmed that the fireballs are hot enough and dense enough to produce quark-gluon plasma. They have found an excess of particles containing “strange” quarks and a dearth of ones containing “charm”—both of which are side effects predicted by quantum chromodynamics. (Strange quarks and charm quarks are exotic kinds not found in ordinary particles.) It all amounts to a powerful case that CERN has been creating quark-gluon plasma—but it does not amount to proof. “The problem is they haven’t been able to observe it directly,” says Tom Ludlam, a physicist at Brookhaven National Laboratory. blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30blob:https://quarxtheories.com/1125c442-e001-430e-a033-2d5e0f0f8b30', 'Brookhaven’s Relativistic Heavy Ion Collider, which is scheduled to begin doing physics this summer, will collide nuclei of gold at 10 times the energy possible at CERN and so achieve temperatures that will allow a quark-gluon plasma to survive a tiny moment longer. As the quarks cool down from a trillion degrees, they should emit heat radiation, in the form of gamma-ray photons. That is the most direct possible signal from the quark-gluon plasma, and Brookhaven’s collider should be able to detect it. You can think of it as the flash of light the universe emitted when all its protons were born.', 'Even the scientists at Brookhaven won’t be able to finally answer the question of where protons come from. A central mystery will remain. Inside a proton, as gluons come and go, as quarks and antiquarks come and go in their numberless swarms, one number remains constant: There are always three more quarks than there are antiquarks. Those are the quarks that, “at the very crudest level,” as Wilczek puts it, make up the proton. Why are they matter and not antimatter? Why is the universe made of matter and not antimatter? The answer goes beyond quantum chromodynamics. A slight imbalance between quarks and antiquarks, if Wilczek and other theorists are right, was already present in the primordial quark-gluon plasma. Understanding its origin will require accelerators that reach even higher energies, such as CERN’s Large Hadron Collider. It will require new kinds of theories—some of which, unfortunately, might demand that we start thinking of particles as tiny loops of string and the universe as having many more dimensions than the four we know and love.', 'As physics evolves, the image of the proton that quantum chromodynamics has given us may come to seem reassuringly concrete and solid—although solid is just what a proton is not. Flying into one—if you can imagine doing that, riding the strong force in a kind of subnuclear glider—would be like falling through Earth’s atmosphere. The upper atmosphere of the proton is a thin cirrus of virtual quark-antiquark pairs; they form a shield for what lies below. As you fall past them, the atmosphere gets denser and denser, the clouds thicker and thicker. Your plane is struck with increasing frequency and force by flashes of color lightning—the gluons. And then, perhaps four fifths of the way through your descent, you emerge from the cloud cover. The ride is calmer now. The lightning bolts have not disappeared; they have fused to a continuous sheet, and somehow you feel at once featherlight and immune from all forces. You’re near the center of the proton now, utterly trapped as you fall toward the asymptote of utter freedom, and you are finding . . . not much.', '“The closer you look, the more you find the proton is dissolving into lots of particles, each of which is carrying very, very little energy,” says Wilczek. “And the elements of reality that triggered the whole thing, the quarks, are these tiny little things in the middle of the cloud. In fact, if you follow the evolution to infinitely short distances, the triggering charge goes to zero. If you really study the equations, it gets almost mystical.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-the-glue-that-binds-everything-together/qotw0228-2/', '2021-02-28T12:00:00Z', '2021-02-28T12:00:00Z'),
  ('l7142', 'what-is-the-glue-that-binds-everything-together', 'bill-h', 'name', null, array['Many physicists subscribe to a set of theories about the sub-atomic universe and its behaviors, known as the Standard Model, and — if I understand the Standard Model correctly — an atom’s nucleus is thought to consist of positively-charged protons and non-charged neutrons. Because a positively-charged particle will repel another positively-charged particle (the way the north pole of a magnet repels the north pole of another magnet) — scientists had to come up with a theory for how a bunch of positively-charged protons could hang tightly together in an atom’s nucleus… so they theorized some ghostly particles called “gluons”… and endowed them with “zero mass” and the amazing power to glue an atom’s nucleus together… but also theorized that these ‘particles’ have no power, and perhaps no existence whatsoever, outside of the nucleus.', 'This past year, it seemed like everything, and everyone, was coming unglued. The economy was coming unglued. Politicians of all stripes were coming unglued. Our healthcare system was coming unglued. Our oil and gas industry was coming unglued. Our relationship with the country that manufactures most of our inexpensive consumer items — China — was coming unglued.', 'We really “know” nothing at all about gluons and quarks, in the same sense that we “know” about the everyday elements of our lives. The smell of bread in the oven, for example. The feeling of acceleration as we make a right turn onto Highway 160. The sound of a county commissioner voting “Aye” to put us deeply in debt for an oversized jail facility. The joy of seeing a FEDEX package on the porch.', 'My question, to explore this morning, is “What is the glue that holds a community together — or a marriage, or a family — and why does the glue seem to fail, in certain situations?”', 'Yesterday, along with the KU press release, we ran an essay by Hilary Dumitrescu entitled “Gather Round the Table.” Ms. Dumitrescu proposes that the hectic pace of modern American life is a key part of the ‘ungluing’ we are currently experiencing — the problems of polarization, blame, division, and an almost unbearable lack of communication, and of compromise.', 'In our rush to do what’s next, we’ve sidelined the table. The results are disastrous and widespread — even reaching Congress. In their book Slow Church, the authors John Pattison and Chris Smith hypothesize that one of the reasons Congress is so divided and, consequently, ineffective is that they do not make effective time for socializing and relationship building, favoring instead to treat their Washington, D.C. offices as a commuter stop in a nonstop whir of activities and cross-country flights. “This is a portrait of a deeply dysfunctional workplace,” say the authors. “If we don’t have time to share meals and nurture friendships, even with our coworkers, we have ceded too much ground to the cult of speed.”', 'Perhaps (with tongue firmly in cheek) this drawing of atomic particles disintegrating, can service equally well to suggest the apparent breakdown of our social institutions?', 'Although I’m not quite clear what the green, spiraling shape at the far right would symbolize.', 'No one, I presume, wants to live in a divided, hostile, disintegrating world. If scientists can spend $7.5 billion to track the disintegration of particles no one can see, feel, hear, taste or smell — that is to say, particles which are, in fact, theoretical — I’d like to see us make at least an equal investment, and effort, to heal the divisiveness and hatred that currently plague our nation.', 'Could the solution be so simple, as Ms. Dumitrescu seems to suggest, as the restoration of shared meals around a shared table? And shared conversation, and shared listening to one another?', 'Assuming of course, that we all wash our hands first, before we sit down. That’s important.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-the-glue-that-binds-everything-together/qotw0228/', '2021-02-28T12:00:00Z', '2021-02-28T12:00:00Z'),
  ('l7173', 'does-anyone-ever-actually-want-to-be-alone', 'cnscsns', 'name', null, array['Believe it or not, NO! Imagine a time when you wanted to be alone. For the sake of this post, let’s say your partner was getting on your nerves. In a rush of discomfort, anxiety and frustration, you left the house to go for a walk. You had to be alone.', 'During this walk, you may have found that you were playing over a story or multiple stories about your relationship and your frustration, etc. Did you really want to be alone? Or did you really just wish you could work through the issue with your partner? Or talk it through with your mom. Or forget about it altogether with your friend. My point is, you don’t really want to be alone, even if the voice in your head is saying, ‘I just need to be alone.’', 'Most of the time this voice speaks to us, it is basically just saying that I need space from the anxiety I am feeling, because the current arrangement is too triggering. Being alone is simply the easiest way of escaping the situation. But just because it is the quickest way out does not mean it is the best. One more layer inward, another voice echoes the words of Chris McCandless as he was writing his last ever journal post in ‘Into the Wild’: ‘Happiness is only real when shared.’', 'Be honest with yourself, and I’ll bet you come to the same conclusion as I did – that this quote is accurate. In any moment, being alone may be better than the current situation, but is not better than being with another or others who you actually want to be with. Being with those we love and who love us is where all happiness lies. Simply put. We are social creatures who depend on this type of herd mentality for not only our happiness but our survival.', 'So ask yourself these questions, and answer them honestly. You deserve happiness.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/does-anyone-actually-ever-want-to-be-alone/qotw0307-2/', '2021-03-10T12:00:00Z', '2021-03-10T12:00:00Z'),
  ('l7169', 'does-anyone-ever-actually-want-to-be-alone', 'allee-g', 'name', null, array['Why are we afraid to be alone? Because we don’t realize this truth… that we never actually are.', 'We can release our fears of being alone by realizing the truth, that we never actually are alone. Separateness is an illusion that has been debunked in the field of quantum physics. We are all made of the same star stuff. Quite literally, your hydrogen atoms were produced in the Big Bang and carbon, nitrogen and oxygen by burning stars (see The Particle Physics of You) and all that star stuff is energetically connected in a seemingly miraculous and yet scientifically proven way. This physical phenomenon is known as Quantum Entanglement… but before we get into this I want to touch on the fear of being alone itself and where we see it in our lives and society today.', 'Diving into the fear — how the “fear of being alone” pervades our society', 'Our fear of being alone is pervasive across our society manifesting in many different ways.', 'Take, for example, dating apps. I think it is safe to say these apps would not exist if we weren’t searching for human connection. But are we looking in the right places? Apps like Bumble and Tinder allow us to simulate connecting with people from our phones, with a one in 3,000 chance of actually connecting with them in real life. (source: Tinder is Not Actually for Meeting Anyone) Not exactly the most effective method, but that is beside the point.', 'The point is these apps exist on the presumption that we are alone, and there is a need to not be alone. And their solution is to give us access to a database of people based solely on location from which to choose who we don’t want to be alone with. I am guilty for having tried it out, but with this perspective, it just seems like a huge waste of our precious time on this planet doesn’t it?', 'Whether we admit it or not, our society has for generations looked down upon and shamed being single. If you ask a majority of our young people today, how many do you think would say they feel pressured to find “the one,” get married, or even for practical purposes to find a partner?', 'Let’s take another example, social media. Snapchat and Instagram ensure a constant flow of FOMO. And as many of us know, along with a diploma, graduating college comes with a tsunami wave of Facebook posts featuring engagements, weddings, babies and so on. We are constantly seeing people with other people, and unconsciously assuming the belief that we need to be with people or at least one other person all the time.', 'There are endless examples of the “fear of being alone” as it presents in our society and many painstakingly failed attempts at combating it.', 'But what if I told you the best way to connect with others was to spend time alone?', 'Hear me out…', 'Diving even deeper — the science of connectedness and Quantum Entanglement', 'At our core we are energetic beings. We are connected by the energy that vibrates in and all around us, from the center of our hearts to the farthest reaches of the Universe. And possibly even further, which you can learn more about here. This is infinite energy, that we have access to all the time, because we are it.', 'So back to the seemingly magical, or what Einstein called “spooky” but scientifically proven physical phenomenon called Quantum Entanglement.', 'As this article published in Nature states, “In the everyday world, objects can organize themselves in just a few ways. For example, two people can coordinate their actions by talking directly with each other, or they can both receive instructions from a third source. In both these cases, the information is communicated at or below the speed of light, in keeping with Einstein’s axiom that nothing in the universe can go faster.”', 'But what if we were to witness instant communication between two objects, in this case living algae cells, separated miles apart? In one of the most famous experiments in Quantum Entanglement algae cells were grown together in a petri dish, then separated in half, one half being brought to a lab miles away. When a low voltage current was applied to one half of the cells, despite the distance and separation, the other half responded in the exact same way, instantaneously.', 'What is so brilliant about these experiments is that they show instant communication between not only subatomic particles, but living cells, separated miles apart. This instant communication does not necessarily disprove Einstein’s otherwise universally accepted belief that nothing in the universe is capable of traveling faster than the speed of light. However, it does show that our very cells are connected by something greater than space and time. And whatever happens to part, happens to the whole.', 'The science is absolutely mind blowing, but the greater point I want to discuss here is what Quantum Entanglement means for us on the level of our human existence. How being ultimately connected to everyone and everything can and should change the way we go about our day, and our lives.', 'As beings made up of living cells, it would make sense that our cells would respond similarly to the cells in the experiment.', 'Let’s sit with this thought for a moment.', 'How would your day change if you realized everything you did, said, and even felt, affected everyone around you? How would you feel about yourself if you knew that you were never alone, but actually were a part of a universe size web of energy that connects you with absolutely everyone and everything?', 'We are all connected by universal energy and information that is constantly communicating and interacting with one another. On a certain level we are always feeling, understanding, and experiencing each other.', 'It is about time we allowed ourselves to release the illusion of separateness and embrace that we are all one energetic existence. Thus releasing judgments of each other (because really we are only judging ourselves), and putting an end to hurting one another (because really we are only hurting ourselves).', 'Sounds all well and good right? But where do we start?', 'How to surface from this fear — releasing the hold the “fear of being alone” has on us by realizing and internalizing that separateness is an illusion', 'The first step to freeing ourselves from the fear of being alone is to realize that that fear does not exist. It can’t exist, because being alone does not exist, because as we just proved, we are all connected.', 'Let me repeat, we are never alone. It is actually IMPOSSIBLE for us to be alone, or separated from any other living and nonliving thing in this beautiful, infinite and unfathomable universe.', 'So what do we do with this information?', 'Mindfulness & meditation — meditation allows us to connect with our true self, the self that is uninhibited and unencumbered by society’s beliefs, and all our learned belief systems for how things are “supposed” to work.', 'Believing something quite as abstract as what Quantum Entanglement suggests, requires we literally rethink everything we have been taught about how the universe works. That’s a hefty goal, but through regular meditation we know scientifically we can rewire our brain and thus unlearn decades of false belief systems.', 'Additionally, by getting quiet and still, we are able to access and influence our own energy field, which is ultimately our connection to everything, and everyone.', 'But thinking about and actually believing that we are all connected are two very different things. Internalizing this information in a way that actually releases our feelings of loneliness will take some work. Part of that work, and undoing of our learned beliefs and negative social stigmas around being alone, will require rewiring those connections in our brain.', 'How do we find those connections in our brain? By taking the time to uncover and actually think about all the experiences we have had that have made those stigmas real for us.', 'So here comes the part where we can’t be afraid to get our hands dirty. It is going to take some time to unearth all the deep rooted unconscious beliefs that have been written into your psyche since the beginning of your life. You are going to have to face your personal experiences, whether that was a past break up, parents’ divorce, or whatever your fear of loneliness has derived from over the years. But the beautiful part is that by doing so, you can take these circumstances, accept them without judgement as a part of your experience and write over them with this new information, that you are in fact unbreakably connected to the world around you.', 'Working through your baggage allows you to thank it for the lesson that it taught you and release it, no longer carrying it into your future self’s experience. Trust me when I say it is not only totally possible, but you will find the greatest peace and new perspective of your life and yourself on the other side.', 'Taking time to get still, reconnect with yourself and actually get to know that person on the inside was the best thing I EVER did. It has quite literally changed my life… and no it hasn’t been easy. I’ve had to dredge up some not very pretty pieces of my past, and work through some not so appealing realities of my present.', 'But believe it or not, when I brought them up and started looking at them through a new perspective, a perspective of acceptance, and not of judgement, everything changed. I realized none of it was about bad, or good, it just was and is. Bad and good are only constructs and beliefs other people have imposed on us throughout our lives. But this is YOUR LIFE and only you get to decide how you want to see it and live it.', 'Truth is, this is the wild west of what our miraculous existence as humans beings actually means. And if you are wondering what I mean by saying miraculous, I’m not talking magic but there is an actual science to the miraculous existence of you, which you can read about here… “The Probability of You Existing.”', 'So now you’re probably thinking, this is great but it doesn’t make me feel any better when I’m home alone on a Saturday night scrolling through my Instagram feed in a melted puddle of FOMO and self-pity. And to this I say… it actually should!', 'Let’s think back to our Tinder example. The article “Tinder is Not Actually for Meeting Anyone” says statistically it takes 3,000 swipes to actually get to the point of meeting someone in person. “Three thousand swipes, at two seconds per swipe, translates to a solid one hour and 40 minutes of swiping (if you don’t stop to actually look at their profile) to go on a single date.”', 'So, you could spend the hour and forty minutes it takes to swipe to find that one person who you can actually meet up with and just hope you connect — or you could spend that hour and forty minutes in meditation working to debunk the root of that loneliness that led you to downloading that app in the first place, and eliminate the feeling for good. Sounds very enticing I know, but seriously we are talking about the quality of your life here!', 'Not to mention the Law of Attraction requires we release our attachments to our desires. And only by doing so will we receive what we desire. Even if that’s a partner or soul mate! Until we release our feelings of desperation and want, which translate to feelings of lack, we cannot vibrate at the frequency necessary to attract that partner into our life.', 'And whether you believe in the Law of Attraction or not, it’s undisputed that people pick up on each other’s vibes. So think about it, are you more likely to attract someone when you exude self-confidence and a desire to find a compatible partner? Or loneliness and the need to be “completed” by someone else?', 'Let’s also circle back to our example of Quantum Entanglement. These living algae cells are so intrinsically connected that they responded instantaneously to electric currents applied to their fellow cells at any distance apart. Knowing this, it could in theory make sense that if we could properly tap into the energy or frequency that is allowing this connection, we could then replicate that experience on our human consciousness level. Just a thought!', 'If you are struggling with loneliness find peace in this… aloneness is an illusion we can overcome by changing the way we see and understand our world and place in it. Your very existence means being alone is impossible. And until then know that the feelings you feel are also being felt by millions of other people around the world. The chance of someone else understanding you is very high to say the least. So if and when you feel ready to take on the fear of loneliness head on, know we are in this together.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/does-anyone-actually-ever-want-to-be-alone/qotw0307/', '2021-03-10T12:00:00Z', '2021-03-10T12:00:00Z'),
  ('l7222', 'what-is-your-mantra-to-restore-your-well-being', 'cnscsns', 'name', null, array['At the end of the day, it comes down to gratitude, compassion, and love – the core emotional vessels into connection and well-being. In Buddhism, there are two sets of four ‘mantras’ that I would like to share. They further exhibit this point. The first is called “The Four Immeasurables.” These are four qualities with boundlessly positive affects – qualities that we always have access to and can habituate our minds to remember and practice. They go as follows:', '• Loving Kindness', '• Compassion', '• Sympathetic Joy', '• Equanimity', 'These reflection points illuminate differently in each of us, however awaken similar responses. They are simply like compasses, pointing the way towards boundless possibility and well-being.', 'The second group of four reflection points are called the “Four Thoughts That Turn the Mind Towards the Dharma.” They go as follows:', '• Impermanence / No self', '• Futility of dwelling in Samsara', '• Karma – Law of cause and effect', '• Precious Human Birth', 'These points of contemplation immediately bring perspective to a situation. They re-align our minds into a bigger-picture experience of consciousness. They are also always available, manifest different reactions in each of us, and yet bring un-deniable well-being to all who give space for them.', 'These two sets of remembrances have brought balance, harmony, and well-being into my life and the lives of many in history. I hope they serve to benefit you, as well!']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-your-mantra-for-restoring-your-well-being/qotw0321-3/', '2021-03-21T12:00:00Z', '2021-03-21T12:00:00Z'),
  ('l7219', 'what-is-your-mantra-to-restore-your-well-being', 'murray-n', 'name', null, array['Chanting is a spiritual discipline believed to improve listening skills, heightened energy and more sensitivity toward others. The practice gained popularity when an album of Gregorian chants by the Benedictine Monks of Santo Damingo in Spain became a best seller. Chants can express devotion, gratitude, peace, compassion and call in light into someone’s life. Here are chants that can help improve your life.', 'Compassionate Buddha', 'The most famous chant in the world is the Compassionate Buddha “Om Mani Padme Hum” which translates to “Hail to the jewel in the lotus.” It is the mantra of the Buddha of Compassion, known by the Chinese as Goddess Kuan Yin. The mantra calms fears, soothes concerns and heals broken hearts.', 'Amazing Grace of Sanskrit', 'Given the name “Amazing Grace of Sanskrit by the author of “Eat, Pray, Love,” Elizabeth Gilbert, the mantra “Om Namah Shivaya” translates to “I bow to Shiva, the supreme deity of transformation who represents, the truest, highest self.” Gilbert translates the meaning to “I honor the divinity within myself” as a reminder that there is a divine energy in everyone and that each person should be treated as if they are divine.', 'Happiness and Freedom', '“Lokah Samastah Sukhino Bhavantu” is commonly associated with the Jivamukti Yoga School. It translates to “May all beings everywhere be happy and free, and may the thoughts, words, and actions of my own life contribute in some way to that happiness and to that freedom for all.” It is a powerful chant that focuses on living a life as a servant to the greater good. It encourages cooperation, compassion and living in harmony, not only among other humans but with nature as well.', 'Medicine Buddha Mantra', '“Tayata Om Bekanze Bekanze Maha Bekanze Radza Samudgate Soha” is a chant that is recited for success, helping to eliminate problems and suffering. It is also recited for healing and to benefit people or animals at all times, even when they are healthy.', 'Mantra of Ganesh', 'The Mantra of Ganesh is dedicated to the Hindu god of wisdom and success who destroys all obstacles. “Om Gum Ganapatayei Namah,” which translates to “I bow to the elephant-faced deity (Ganesh) who is capable of removing all obstacles. I pray for blessings and protection.” The mantra is especially beneficial when facing big challenges and when traveling.ADVERTISING', 'Lakshmi Chant', 'A mantra that translates as a greeting to the Hindu goddess of wealth and prosperity, Lakshmi, “Om Shrim Maha Lakshmlyei Swaha.” The chant asks for Lakshmi’s assistance with material wealth and abundance.', 'Buddhist Money Mantra', 'The Buddhist money mantra, “Om Vasudhare Svaha,” is a prayer to the earth goddess, Vasudhara. The chant should be repeated 108 times in order to be blessed by deities who will shower them with abundance.', 'Interview Chant', 'This chant is perfect when going for a job interview or making a proposal. The words “Pravisi Nagar Kijal Sab Kaaja Hrudaya Rakhi Kosalpur Raja” translate to “Having the impression of Lord Ram, I am entering in the city for doing my work. May all my works and wishes get complete.” It can also be used when you enter an office building or the office of the person you are planning to meet.', 'Mantra for Success', 'When you are not sure what option is right for your success, chanting “Jehi Vidhi Hoi Naath Hit Moraa Karahu So Vegi Daas Main Toraa,” which means “O lord, I am your devotee. I don’t know what to do. So do at once whatever is good for me.” This mantra is said to show the door of success as long as they are practiced with faith and reverence.', 'Manjushri Mantra', 'For those who want to enhance wisdom and improve skills, chanting “Om a ra pa ca na dhih” will increase skills in all types of learning. The more emphasis and times the chant is recited, the more likely it is to succeed.', 'Vajrapani', 'Vajrapani represents the energy of an enlightened mind, which is why it is said that chanting”Om vajrapani hum” will cut through delusion and make the chanter free from hatred. He is often pictured dancing wildly within flames as a representation of transformation. The chant helps gain access to excessive energy and even the chant sounds energetic.', 'Peaceful Life', 'If it is a peaceful life you seek, the mantra “Sarveshaam Svaastir Bhavatu, Sarveshaam Svaastir Bhavatu, Saveshaam Poornam Bhavatu, Sarveshaam Mangalam Bhavatu, Om Shanti, Shanti Shanteeh” is said to bring peace and tranquility. The phrase translates to:', '“May health abound forever
May peace abound forever
May complete abundance abound forever
May auspiciousness abound forever
Om Peace, Peace Peace.”', 'Health, Strength and Peace', 'There are several mantras that can be used to bring health, strength and peace. For health, chanting “Aham Aarogyam” which translates to I am healthy, is said to bring health, while adding “Om Trayamabakam” brings health for a longer period. For strength, the chant suggested is “Aham Brahmaasmi” which means “I am God,” while peace can be obtained by chanting “Om Shanti Shanti Shanti.”', 'Difficult Times', 'It is said that the chant', '“Mookam karoti vaachaalam
Pangum langhayatey girim
Yatkripaa tamaham vandey
Paramaananda Maadhavam”', 'Can make the cripple climb mountains and the mute speak eloquently. The mantra asks for grace in order to ease someone out of difficult situations. It means:', '“I salute that Madhava
The source of Supreme Bliss,
Whose grace makes the dumb man eloquent
And the cripple cross mountains.”', 'Bhagvad Geeta Verse', 'The 15th verse in the 15th chapter of the Bhagvad Geeta is chanted when a difficult situation becomes worse.', '“Sarvasya chaaham kridi sannivishto
Mattas smritir inaanama pochanamcha
Vedaishcha sarvaair ahameva vedyo
Vedaanta krid veda videva chaaham”', 'In the translation, Krishna says that He is seated in the hearts of all men and women so someone who is causing you difficulty is aware of what you are experiencing as well. By placing your trust in a higher power, whatever is right is what will happen.', 'Seeking Success', 'For those seeking success, chanting', '“Krishna Krishna Mahaayogin
Bhaktaanaam Bhayankara
Govinda Permaananda
Sarvey Mey Vash Maanay”', 'Is said to bring that success. The translation asks Krishna to give Supreme Bliss and to bring everything to your favor.', 'Chant for Prosperity', 'This chant contains the eight facets of God and uses for repetitions in each verse to give the power necessary to break down barriers from the past and give power to the person chanting.', '“Har Har Har Har Gobinday
Har Har Har Har Mukhunday
Har Har Har Har Udharay
Har Har Har Har Aparay
Har Har Har Har Hariong
Har Har Har Har Kariang
Har Har Har Har Nimamay
Har Har Har Har Akamay”', 'Ancient Mantras', 'A simple chant is designed to be an homage to Buddha, “Namo AmitaBha” gives honor to the Buddha of Boundless Light, while “Ham-Sah” is a Hindu variant of “I am that I am” meaning “I am that.”', 'Amithaba', 'The chant that is the sacred mantra of Buddha, Amithabha enhances compassion while bringing blessings each time it is spoken. By chanting “om ami dewa hrih” you will be protected from dangers and obstacles.', 'Green Tara Mantra', 'This is often chanted to overcome physical, mental or emotional blockages, although it can also be used for blockages in relationships. “Om tare tuttare ture soha” helps you release hope for a particular outcome and bring the energy back to yourself, generating inner peace and clarity.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-your-mantra-for-restoring-your-well-being/qotw0321-2/', '2021-03-21T12:00:00Z', '2021-03-21T12:00:00Z'),
  ('l7216', 'what-is-your-mantra-to-restore-your-well-being', 'therese-b', 'name', null, array['Back before there were psychiatrists and therapists, way before the introduction of Prozac and Xanax, people were using mantras to calm their nervous systems and sooth symptoms of depression and malaise. In fact, the earliest mantras were used by Hindus more than 3,000 years ago. Employed by Buddhists, Christians, Taoists, and persons of most faith traditions, mantras defined in the strict sense consist of hymns, chants, syllables, or groups of words that are considered sacred, having psychological and spiritual powers. I use the term loosely to refer to a phrase repeated over and over, or whenever a painful emotion or thought surfaces. During periods of acute depression and anxiety, I have uttered these words as many as 500 times a day. They are especially useful when caught in tormenting ruminations.', 'Focused repetition of a soothing word or phrase, called autogenic training, helps you to relax and primes your body’s parasympathetic nervous system. A 2008 study at the University of Melbourne in Australia found that autogenic training, along with other relaxation techniques like progressive muscle relaxation and imagery, reduced depressive symptoms among some participants.', 'It’s best to develop your own mantras that will appeal to your emotions, ones that make you feel safe and are able to calm you down. Here are ten that have helped me.', '1. This Too Shall Pass', 'The reminder of impermanence is a powerful antidote to fear—that everything is passing, even those emotions, thoughts, and situations that feel permanent and etched in our brains forever. Joseph Goldstein, co-founder of the Insight Medication Society, once said that “Wisdom is the clear seeing of the impermanent, conditioned nature of all phenomena, knowing that whatever arises has the nature to cease. When we se this impermanence deeply, we no longer cling; and when we no longer cling, we come to the end of suffering.”', '2. Just for Today', 'I can do most things if I know it’s a 24-hour gig. By reminding myself that I only have to give this day my best shot—or maybe even the next 15 minutes—suddenly what I thought was truly impossible. Just as I repeated “one day at a time,” to myself over and over again when I quit drinking, “just for today” prompts me to get back in the moment, and not to sweat too much about a month from now or ten years out. It forces me to concentrate on now, which is the only thing that matters and the only thing I can control.', '3. I Will Get Better', 'One of the most painful symptoms of depression is the despair and hopelessness you feel—the certainty that you will feel this way for the rest of your life. Before she died, my great aunt Gigi, who struggled with depression her entire life, left me with one word of advice: always repeat, “I WILL get better.” “Keep saying it over and over,” she said, “even when you don’t believe it.” She told me that eventually I would believe it, and those four words would bring me hope. She was right.', '4. This Is a Moment of Suffering', 'In her book, Self-Compassion, Kristin Neff, Ph.D. offers a beautiful mantra she developed to help her deal with negative emotions, a reminder to treat herself with self-compassion when discomfort arises: “This is a moment of suffering. Suffering is part of life. May I be kind to myself in this moment. May I give myself the compassion I need.” I simplify it to the first sentence, which also makes me think of American Buddhist Pema Chodron’s instructions to “lean into the sharp points” when we are faced with fear, uncertainty, panic, and pain.', '5. May My Life Be Of Benefit To All Beings', 'I acquired this mantra in meditation teacher Tara Brach, Ph.D.’s book, Radical Acceptance. One of the ways we can respond to pain is by transforming it into compassion. “As we transform suffering into compassion, we realize our interconnectedness with all of life,” she writes. Sometimes I also say “Make me an instrument of your peace,” the first line of the Prayer of St. Francis. Both mantras help me to use compassion to transcend my pain.', '6. I Am Breathing In, I am Breathing Out', 'In his book, You Are Here, Vietnamese Zen Buddhist monk Thich Nhat Hanh instructs us to say with each in-breath, “Breathing in, I know that I am breathing in.” And with each out-breath, “Breathing out, I know that I am breathing out.” Mindful breathing, he explains, is the bridge that unites the body and the mind. By concentrating on our breath, we generate peacefulness and calm. This abbreviated mantra helps me stay mindful of my breath.', '7. Be Not Afraid', 'The words “fear not” are used over 80 times in scripture, and “be not afraid” or the equivalent, another 30 times. There is no scripture passage that calms me down more than these three words. In fact, when I would begin to panic even as a grade-schooler, I used to sing the lyrics of the song “Be Not Afraid.”', '8. Let It Go', 'It’s hard not to hear Elsa belting out the lyrics to “Let It Go” (from Disney’s “Frozen”) when these three words are assembled, but this phrase offers wisdom for everyone, not just those cursed with a syndrome that makes everything into an icicle. It’s especially helpful for me when I’m caught in obsessive thinking, ruminations that take on a life of their own.', '9. There Is No Danger', 'As those who have experienced panic know, anxiety can often feel like you’re dying—that there is some inherent danger in your situation that could end your life. A great mantra for me, then, to keep my anxiety in check, is “There is no danger.” I picked up this gem in the book Mental Health Through Will Trainingby psychiatrist Abraham Low. He writes, “You will realize that the idea of danger created by your imagination can easily disrupt any of your functions … If behavior is to be adjusted imagination must interpret events in such a fashion that the sense of security … overbalances the sentence of insecurity.”', '10. I Am Enough', 'Since many of my ruminations stem from feeling unworthy on some level, I remind myself that I am enough. I don’t need kids on the dean’s list nor do I need to be a superstar blogger with millions of Twitter followers to earn my place in this world. I am enough as I am, as a child of God, doing my best while battling a chronic health condition.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-your-mantra-for-restoring-your-well-being/qotw0321/', '2021-03-21T12:00:00Z', '2021-03-21T12:00:00Z'),
  ('l7243', 'where-is-your-mind', 'kirsten-h', 'name', null, array['In all questions of importance, I consult Kim Deal. She was in the Pixies, Throwing Muses, the Breeders, and she helped get Tanya Donnelly started with another of my favorite bands, Belly. You might know the lyrics:', 'Where is my mind? Where is my mind?', 'Way out in the water, she is swimmin.', 'If you’ve ever gotten a really good hand or foot massage, you know the feeling of your mind being somewhere other than in your head.', 'If you’ve ever cringed while watching a video of someone getting injured, you know the feeling of your mind being somewhere other than in your head.', 'At that moment, you are transported through time and space, into the head of another person.', 'If you put on a VR headset and fly around in a drone, your mind might literally be soaring over the Alps.', 'When I watch this video, my mind is with Kim Deal. I’m going “Woooo-oooo” in the background vocals.', 'When you read my books or my answers, you are transported into my mind.', 'Welcome! Dive in. The water’s fine.', 'Is the brain the same thing as the mind? I don’t think so. The brain is the substance, the mind is the focus of the substance, and consciousness is the mind telling the brain what it is doing.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/where-is-your-mind/qotw0328-4/', '2021-03-28T12:00:00Z', '2021-03-28T12:00:00Z'),
  ('l7239', 'where-is-your-mind', 'daniel-s', 'name', null, array['In consciousness. What does that tell you?', 'I can’t say what consciousness is other than it is what you are. The body could be said to be in the mind. Consciousness is the only ‘thing’ that is not inside something else, but everything is within it, is it. Different aspects of consciousness have different functions. The mind has a particular function that has to do with physical reality.', 'The idea is that you generate, with your non-physical consciousness, electrical energy ﬁelds. That concept, acting through the symbol of the physical brain, generates a reﬂection – a symbolic reﬂection – of your consciousness in physical terms. And you call it mind, or mentality.', 'It might be better to think of the mind as an energy-translator. One side transmits non-physical energy, and the translator gives out a physical picture, using certain filters which include your unique blueprint, beliefs and definitions, personality construct.
If you’ve heard of the concept of “higher mind” communicating with “physical mind”, this is what is meant. Because the physical mind is designed only to translate what it receives and merely perceive “reality”. Receive and perceive. The higher mind conceives. Therefore, when you are inspired, for example, you are so attuned to your higher mind that it’s as though the translation of the non-physical information is more accurate. So you feel lifted, above your own mind.', 'The simple version: mind is the physiological representation of consciousness.', 'It allows there to be activity of consciousness in apparent matter. If you, as consciousness, weren’t on an apparent physical exploration, there would be no mind. No need. But as long as you project yourself into this “reality”, the mind is in full operation.', 'Now, the mind is not inherently negative. It’s just a mechanism for the conversation between non-physical and physical. All things become negative when they are asked to do a job they are not designed to do. Take humans, for example, give an office job to a free nature spirit type, and s/he will sooner or later decay. Same thing goes for the mind: give it the responsibility of controlling everything, of trying to figure out everything – it will become bitter, and then it will blame the world and everybody in it. Simply, the mind merely receives and perceives, using the symbol of the brain. Ask it to do more than that, and you will be assigning too much work to that which does not know how to handle it. The experience of that is what’s called “being caught up in one’s mind”. Therefore, the solution at this level is, “shut up, receive, perceive”. You can be ore nice about it and say “calm down, receive, perceive” 😉', 'The balanced mind may or may not be quiet. There is an idea in spirituality that the mind has to remain quiet, or else something’s wrong. That is because all we know is negative mind. But when you are in high frequencies like joy, inspiration and excitement, there might be a delicious “conversation” occurring with the higher aspects of yourself (for you are a multi-layered consciousness). For example, there are moments (everyone has) where so many pieces and bits of information “all of the sudden” fall into place. An “a-ha!” moment, where everything suddenly makes sense. The mind is then translating tons of information very fast, and that’s because you are in a non-resistant frequency (like joy). Also, what we refer to as silence or stillness is actually a state of TONS of energy and information moving. Things that move at infinite speed seem to be standing perfectly still, because they are everywhere at once. This is the state of infinite momentum, infinite acceleration. But it’s also stillness.', 'Yet if the mind needs to think, let it think. If you want to talk to yourself, talk to yourself. It’s much better not to suppress it, but to allow it while being conscious. Some thinking and self-talk is extremely creative, efficient and productive (surely I’m not talking about the type that goes in loops and spins blame stories, drowning in problems). It can be one way to be more connected to yourself. That’s because all day every day you are hearing others’ thoughts and talking, and sometimes you just really need to hear your own. Speaking to yourself, consciously, is not a sign of craziness, simply a way to hear yourself better.', 'I bring these points up because certain things that are presented in spirituality cause people to suppress themselves. That is never an wholistic approach.
The mind, from this perspective, is not an enemy. Especially when you work with your filters: remove a filter, “reality” changes. When you get really playful with this, you will blow your own mind how what you perceive as a limitation can be completely disappeared. “It’s all in the mind”, as they say. But do they really understand it?']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/where-is-your-mind/qotw0328-3/', '2021-03-28T12:00:00Z', '2021-03-28T12:00:00Z'),
  ('l7235', 'where-is-your-mind', 'jeremy-j', 'name', null, array['The answer to this question, in my opinion, depends on which mind one is talking about.', 'Many people contend that our mind is simply a construct of our brain and thus resides within the brain. However, in my CSD (Conscious Subconscious Dynamics) system, our two minds reside in different areas. My contention is that our conscious mind is a product of our brain and does reside within the activity of our neurons by way of electrical and chemical reactions.', 'Yet, I believe our subconscious mind resides within the entire body with a heightened focus pertaining to the brain, heart, gut, and genital areas.', 'So again, to answer the question, “where does the mind reside”, would depend on which mind one is referring to (conscious or subconscious).', 'This is not to say that our total experience of consciousness is simply the result of brain activity. Instead, what I am conveying is that our conscious mind, in of itself, is a product of our brain. Yet the total conscious “experience” goes beyond the construct of our conscious mind.', 'For example, the sensation of being “within one’s body” is a perception generated by the subconscious mind. Again, the subconscious is an integrated part of every cell of our physical self.', 'Typically I try to refrain from getting too much into my personal spiritual beliefs. Yet, to expand upon this question, I will say I view total consciousness as the end point of a large funnel of information/experiences.', 'It helps to think of it like a chain. The conscious mind is connected to the subconscious, the subconscious is connected to the universal consciousness, and the universal consciousness is connected to the All.', 'This flow from one part to the next, ending with us, is what gives us our total consciousness perception. A flow of knowledge where our two minds are but two links in the chain. So while our minds either can be said to reside within our brain or our body, our complete conscious experience resides as an integrated component of the totality of reality and beyond…']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/where-is-your-mind/qotw0328-2/', '2021-03-28T12:00:00Z', '2021-03-28T12:00:00Z'),
  ('l7233', 'where-is-your-mind', 'n-alvi', 'name', null, array['Ryle: That’s a category mistake.
Churchland: ‘Mind’ is just a folk concept; you don’t really have one of those.
Smart: In your skull.
Hume: Whose mind?
Searle: Well it’s not in the Chinese Room.
Clark: All over the place and especially in your iPhone.
Descartes: It’s not located in space, but it’s also very near to your pineal gland.
Chalmers: In every possible world where you aren’t a zombie.
Dennett: In the eye of the beholder but not just in the eye of the beholder.
Spinoza: Everywhere God is.
Penrose & Hameroff: In your microtubules.
McGinn: We’ll never know!
Turing: Represented here, on this strip of tape.
Berkeley: As opposed to what?']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/where-is-your-mind/where-is-your-mind/', '2021-03-28T12:00:00Z', '2021-03-28T12:00:00Z'),
  ('l7268', 'why-not', 'nick-s', 'name', null, array['In the end, the basic matrix are the dual questions: ‘Why?’ and ‘Why not?’ Together, they form the basic structure of human understanding. They are the basic questions that underline our unique curiosity. ‘Why’ is like looking at the sky. It is our right-brained, feminine, heart-based question. Whereas ‘Why not’ is our left-brained, masculine, rational-minded question – more like looking straight ahead. The two questions make up our rational and heart-minded experiences of consciousness, and are equally valuable questions to ask.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/why-not/why-not-3/', '2021-04-07T12:00:00Z', '2021-04-07T12:00:00Z'),
  ('l7266', 'why-not', 'cnscsns', 'name', null, array['There are always a million justifications for ‘why not’. But how many of them are really worth listening to? Is this not just a familiar, fear-based way of processing our life and the opportunities that arise? If we are accustomed to asking ‘why not _____’ all the time, we are creating pathways to remain stagnant, limit growth, etc. There’s really very few reasons to ask ‘why not’ and far fewer than we think there are. My answer, then, is no answer. Question why we ask this question in the first place. Are we being rational or asking from a place of fear?']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/why-not/why-not-2/', '2021-04-07T12:00:00Z', '2021-04-07T12:00:00Z'),
  ('l7264', 'why-not', 'big-dave', 'name', null, array['When do we ask this question? It’s almost always just a solidification of a plan. For example, your friend asks you if you want to go cliff jumping. ‘Why not?’ aka, ‘Yeah, sure!’ Occasionally it’s used as an opposition to the question of ‘why’. For example, ‘Why are you going cliff jumping?’ ‘Why not?’ We ask the question ‘why’ quite a bit, and paradoxically, the question of ‘why’ is more dissuasive of doing something than the question, ‘why not?’ ‘Why cliff jump?’ as opposed to ‘why not cliff jump’. The latter is much more persuasive and optimistic way of thinking, even as it seems more negative when it stands alone.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/why-not/why-not/', '2021-04-07T12:00:00Z', '2021-04-07T12:00:00Z'),
  ('l7297', 'to-what-extent-is-happiness-available-to-everyone', 'gaia', 'name', null, array['Given the deeply subjective nature of ‘happiness’, it should technically be independent of conditions and other factors. According to the Buddha’s teachings, our ‘happiness’ is a result of clear understanding – of experiencing reality as it actually is. That includes recognizing impermanence as well as the non-existence of an independent ‘self’. These recognizitions lead to non-grasping and fulfillment. Those who have realized these truths are happy, whether they are financially wealthy or not.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/to-what-extent-is-happiness-accessible-to-everyone/to-what-extent-is-happiness-available-to-everyone/', '2021-04-11T12:00:00Z', '2021-04-11T12:00:00Z'),
  ('l7294', 'to-what-extent-is-happiness-available-to-everyone', 'beti-s', 'name', null, array['At least once in their lives, everyone has probably heard a version of the saying, “money can’t buy happiness.” Some even justify this by referencing the two billion people around the world who live in extreme poverty but still experience joy. When westerners visit impoverished communities, it is common to hear descriptions like “despite having so little, they were so happy.” Even some research supports the idea that a lower GDP can lead to a more fulfilled life. However, it isn’t a straightforward relationship. When addressing global poverty, the simplification that poor people are happier can be dangerous and undermine the harsh realities of the world’s poor. Although wealth isn’t correlated with happiness, neither is poverty.', 'Wealth and Happiness', 'On several occasions, research has shown that people living in poverty report lower life satisfaction, lower subjective well-being and lower levels of positive emotion. Even the World Happiness Index ranks the high-income countries as the happiest. Africa is home to the majority of the world’s poor and has the least happy countries. This contradicts the notion that poor people are happier.', 'The research found happiness related to wealth when comparing people with higher incomes with those of lower incomes. However, it also compared people living in high-income countries with those living in low-income countries. In a study involving 132 countries, researchers found that in order to have an average life satisfaction rating of five out of 10, people needed to make an average of $3,000 per year.', 'Wealth and Fulfillment', 'The same study also evaluated the levels of fulfillment that people with various income levels reported. It found that poorer people reported higher levels of meaning in their lives. While only 66% of people in wealthier nations reported having meaningful lives, this number rose to above 95% in impoverished countries. Although it may appear that this is to do with the money these people had, it may actually have more to do with religious faith. Only 25% of Europeans identify as highly religious compared with 90% of Africans. Additionally, even high-income African’s reported higher happiness levels than similar income Europeans.', 'Another study has shown that happiness and fulfillment are separate topics. While fulfilling immediate needs increases happiness, it doesn’t necessarily impact fulfillment. There are many ways human beings find meaning. In wealthier nations, people that are more philanthropic repeatedly report leading more meaningful lives. As it happens, solving global poverty benefits the life satisfaction of poor people as well as those who help them.', 'Addressing Global Poverty', 'Although money doesn’t buy happiness, it does buy basic necessities like food, safe water and shelter. Around 43% of the world can’t afford a healthy diet, two billion people lack access to safe water and more than 1.5 billion are homeless. Without these basic needs, it is unrealistic to suggest that poor people are happier.', 'The notion that poor people are happier is outdated and not supported by research. Although various cultures have various ways of measuring happiness, research shows that certain things are universally essential. Addressing global poverty requires that people consider basic necessities as human rights and not privileges. By respecting more human rights and providing solutions to global poverty, the world is essentially happier.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/to-what-extent-is-happiness-accessible-to-everyone/qotw0411-2/', '2021-04-11T12:00:00Z', '2021-04-11T12:00:00Z'),
  ('l7290', 'to-what-extent-is-happiness-available-to-everyone', 'katie-g', 'name', null, array['1. Happiness is not objective.', '2. If nothing but happiness existed, we wouldn’t have the ability to notice our own happiness.', '3. Being happy isn’t the only beautiful experience in life.', '—', 'I’m Taoist. One of my favorite lines of the Tao Te Ching is from Poem Two. The translation I love most (Ursula K. Le Guin) goes like this:', '“Everybody on earth, knowing that beauty is beautiful, makes ugliness. Everybody knowing that goodness is good, makes wickedness.”', 'These are human distinctions and human inventions and human definitions.', 'To make happiness, we make sadness.', 'Not only do we create these definitions ourselves, we then all go around disagreeing with each other about them!', 'Happiness is not objective.', '—', 'More Tao Te Ching, Poem Two from Ursula K. Le Guin:', '“For being and non-being arise together.”', 'And from the Feng, English, and Lippe translation:', '“Therefore having and not having arise together.”', 'We can’t be happy or have happiness without also being able not to be happy or not to have happiness.', 'Ask a totally red-green colorblind person to tell you what red and green mean to them, without thinking of what anyone else has ever told them. Tell them to use only their personal experience. They’re going to tell you about grey.', 'It is contrast that makes things visible or noticeable.', 'How weird would you feel if you didn’t know what sadness or anger or fear were? What if none of us did?', 'If we were all happy, we would just call it “emotion” or “normal.”', 'If nothing but happiness existed, we wouldn’t have the ability to notice our own happiness.', '—', 'But we can absolutely all have happy times in our lives – and more importantly, we can recognize more qualities of a moment, a person, or a life than just “happy.”', 'The idea of even one person* never experiencing happiness could probably power the Infinite Improbability Drive through a significant hyperspatial leap. Theoretically it’s possible, and I’m sure we could imagine scenarios, but I’ll just make my next point instead.', 'Think of the music you like. Is it always happy music that you like the most? No, lots of us get sick of Christmas carols or sappy, overplayed pop love songs.', 'Well, in order to write sad songs, angry songs – to create anything unhappy in any artistic medium that anyone else is gonna deeply relate to, you have to know unhappiness personally or through someone very close to your heart.', 'Do you like Linkin Park? Three Day’s Grace? Nirvana?', 'You know that beautiful music did not come out of happy people.', 'I mean, seriously, have you listened to anything by Kesha or Lorde or Lady Gaga recently?', 'Yet we also know those artists had happy times in their lives.', 'Do you like *any* music based in rock? R&B? Hip-hop? Jazz? Ragtime?', 'These are genres – vast, international genres – rooted in music that is literally. called. the.', 'BLUES.', 'Where would music be without the horrific, bloody, painful past of the slave trade?', 'NO-FUCKING-WHERE.', 'And yet, BEAUTIFUL, even HAPPY music evolved from bloody roots.', 'Swing dancing and club dancing are some of the most blissful, fun experiences I’ve ever had in my life. I know where those roots go, though. It wasn’t happiness that gave me my happy music to dance to.', 'Strange Fruit is one of the most deeply moving, bone-chiling, gut-wrenching, breathtaking songs I’ve ever heard. That song is so beautiful and meaningful and powerful that I usually have to stop whatever I’m doing, no matter who’s singing it, so I can shut my eyes, listen close, sing along, and play it twice. Happy?? Of-fucking-course not. And yet it’s probably one of my top ten favorite songs – even as much as I hate picking favorites.', 'I think a bluesy ruby is more beautiful than a sparkly pop diamond any day.', 'Being happy isn’t the only beautiful experience in life.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/uncategorized/qotw0411/', '2021-04-11T12:00:00Z', '2021-04-11T12:00:00Z'),
  ('l7317', 'are-there-any-questions-that-are-better-left-unasked', 'cnscsns', 'name', null, array['Curiosity is an essential quality in anyone who seeks truth. Intrigue, openness, questioning – all of these attitudes lend themselves to seeing through the veil and experiencing direct reality. But are there any questions that don’t exactly further the process of awakening? Yes. Here’s why:', 'We must look beyond the questions directly and ask ourselves: Why am I asking this question? Is it out of genuine interest? Or is it going to offer clarity or further confusion? These are important check-ins. Why? Because much of the time, we already have the answers. We already have the map, simple and pure, that does not need to be further complicated.', 'What is your stomach doing to your food right now?', 'This question may be interesting to pursue, but also may be a distraction, unnecessary, gross, etc. It may not be a question worth asking. There are many other such questions. However, this is deeply subjective, and ultimately, each of us knows which questions we should ask and which we may be better off leaving unasked.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/are-there-any-questions-that-are-better-left-unasked/qotw0418-3/', '2021-04-19T12:00:00Z', '2021-04-19T12:00:00Z'),
  ('l7314', 'are-there-any-questions-that-are-better-left-unasked', 'sid-k', 'name', null, array['The Buddha would say yes, there are many questions better left unasked. They should not be ignored, but attended to and set aside, to avoid the problem of obsession that Anonymous mentions in his post.', 'The Buddha suggested that only a very specific set of questions was worth asking. He saw the human condition, while inherently capable of joy and peace, currently full of suffering and confusion. And it takes time and energy to end that suffering and answer the questions that matter, such as:', '• What is the nature of suffering?', '• What are the origins of suffering?', '• Is it possible to bring an end to suffering? (good news: Yes!)', '• How do I bring an end to suffering?', 'and four more questions about how to bring an end to suffering and how to cultivate joy and peace:', '• When I see a seed of suffering, what do I do to keep it from growing?', '• When suffering has grown up, what do I do to cut it down or root it out (like a weed)?', '• When I see a seed of joy or peace, what do I do to help it grow?', '• When I see a wonderful, healthy growth of joy and peace, how to I nourish and maintain it?', 'These are practical, beneficial questions. Answer them, and apply the answers, and we create lives of joy and peace, as free of suffering as we can make them, for ourselves, our loved ones, the larger society, and the world.', 'The Buddha saw this as urgent work. So time spent on philosophical questions was time taken away from the urgent work of joy and peace, and quite harmful. He compared philosophical speculation to a man, hit by a poisoned arrow, refusing treatment until he knew the nature of the poison, the nature of each part of the arrow, and the archer. He will die before his questions are answered.', 'So the Buddha held that all questions of philosophical speculation, all notions of existence and questions about existence, all religious questions about the nature of things – Creator and creation, the beginning and end of time, reincarnation – all these topics were questions best not asked and answered and made into matters of contention.', 'We have more important work to do: Let’s bring an end to suffering and share joy and peace.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/are-there-any-questions-that-are-better-left-unasked/qotw0418-2/', '2021-04-19T12:00:00Z', '2021-04-19T12:00:00Z'),
  ('l7336', 'if-it-was-revealed-that-your-whole-life-was-a-truman-show-how-much-have-you-ques', 'gaia', 'name', null, array['As did Truman Burbank in the movie, I believe mankind is motivated to seek truth on an instinctual level. Sure, we are sheeps to some extent, but we also ask questions – and are the only species to do so. We have intuition – a quality that activates subconsciously, unpredictably, and powerfully. Whether we ‘want’ to escape a ‘Truman Show’ or not, the clues will present themselves and we will follow our innate curiosity towards truth.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/uncategorized/if-it-was-revealed-that-your-whole-life-was-a-truman-show-how-much-have-you-questioned-the-reality-to-which-youve-been-presented-2/', '2021-04-25T12:00:00Z', '2021-04-25T12:00:00Z'),
  ('l7334', 'if-it-was-revealed-that-your-whole-life-was-a-truman-show-how-much-have-you-ques', 'big-dave', 'name', null, array['Honestly, hardly at all. Sure, I’ve asked the big questions. I’ve done a bit of exploring. I’ve unshackled myself from some of the most obvious constraints of modern western socialized life. However, when I think about it, I have never come close to REALLY perceiving an escape route – To REALLY questioning this reality as it’s been presented. This whole existence feels distant and unfamiliar. As A.E. Housman said: ‘I, a stranger and afraid, in a world I never made’ – encapsulates this experience best.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/if-it-was-revealed-that-your-whole-life-was-a-truman-show-how-much-did-you-question-the-reality-to-which-you-were-presented/if-it-was-revealed-that-your-whole-life-was-a-truman-show-how-much-have-you-questioned-the-reality-to-which-youve-been-presented/', '2021-04-25T12:00:00Z', '2021-04-25T12:00:00Z'),
  ('l7338', 'if-it-was-revealed-that-your-whole-life-was-a-truman-show-how-much-have-you-ques', 'cnscsns', 'name', null, array['As a kid, I used to experience my life as Truman Show – esq. Why? Because I was in disbelief of how fortunate my circumstances were. I was not a victim, but the benefactor of seemingly undeserved good fortune. As I’ve grown up, I’ve grown to feel more and more like a victim. Now, I feel like a slave to circumstance, a prisoner to my own mind, an a puppet to an unknown force.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/if-it-was-revealed-that-your-whole-life-was-a-truman-show-how-much-did-you-question-the-reality-to-which-you-were-presented/if-it-was-revealed-that-your-whole-life-was-a-truman-show-how-much-did-you-question-the-reality-to-which-you-were-presented/', '2021-04-26T12:00:00Z', '2021-04-26T12:00:00Z'),
  ('l7362', 'what-is-the-effect-of-language-on-a-society', 'talilah-c', 'name', null, array['Languages are semiotic systems, that is, systems that create meaning (through concepts for instance). These work as patterns of relevance and thus point out what “matters” to the speakers (ex: there exist several spectrums of colours described by different languages). Words and metaphors bear meaning and direct the attention of speakers to precise phenomena. Thus, a language may to a certain extent reflect a society’s practice of the world, as a certain variation of a language may impact and redirect the society’s attentive Energy to other phenomena (ex: gender neutral pronouns). Still, there are no “pure” language in the sense that languages are based on a multiplicity of variations that differ according factors such as geography, identities, social-class, and so on.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-effect-of-language-on-a-society/what-is-the-effect-of-language-on-a-society/', '2021-05-02T12:00:00Z', '2021-05-02T12:00:00Z'),
  ('l7358', 'what-is-the-effect-of-language-on-a-society', 'martin-g', 'name', null, array['First. There is no communication without language, even when you move you express something, you have a body language. And you might think, but that’s natural we are talking about the constructed language.', 'Body language is a construction too, it has some base on nature (you don’t great people hitting them in the face), but kisses have diferent meanings in diferent countries, smiles too, and look into the yes can be a good or bad thing depending where you are. So, there is no way to express anything without a language. Umberto Eco has even said that there is not such a thing like a iconic sign, meaning every sign is related to a learnning process and a society.', 'Language is the way we organize the world, the way we make sense of anything that happens to us by link it to a category, idea or meaning.', 'Second. Language is the way we fit in a society, by sharing meanings and a way of think. Let’s think about hierarchy.', 'In Spanish you have “Usted” for when you talk to a person you think really reserve respect. Que es lo que usted piensa? (What do you think?). Then there is “Tu” that means you have confidence with the person you talk. Tu que piensas?. And then you have “Vos”, that is use in some countries, like Argentina and Colombia, and means you are very confident with someone.', 'I know there is some form more respectful than “You” in english, but i have hardly ever seen them in use. It seems to me, even when i am not an expert, than english language generally imply higher level of respect than spanish for people you talk with.', 'And then we got japanesse, that not only ask you to change the way you talk to another depending their rank, but also the way you talk about you (the I) according your position.', 'Third. Language tell a lot about how we see the world and life. This is a very complex point, but i would like to give just one small example. Even when i am not a feminist, neither a machist, there is a word that say a lot about machism, at least in spanish speakig culture. That word is “puto”.', 'You might know words in spanish have a feminine way and a male way. So there is “puta” and “puto”. Now “both have a negative connotation, but the denotation of the words differs.', 'Puto: Is the man who have sex with other men. Sometimes also a coward. But the first meaning is a clear insult and express the way the societies look at gay people. Man shouldn’t have sex with man, that is the idea.', 'Puta: is the woman who have sex with a lot of men. So, women shouldn’t do that.', 'This is interesting. Because man who have sex with a lot of women are ok. You are not call puto because of that, you are call puto when you actually don’t have sex with women. Also, it seems lesbianism it is not in the same negative level as homosexuality among men.', 'Of course, a word it is not enough to analize a society. Don’t ever do that, it is lazy and silly. But i hope this examples give you and idea of all the forces and meanings that are in the work in any language.', 'Yes, the language rules your thinking, even when you rebel to the meanings the language have, you do with the tools it gave you.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-the-effect-of-language-on-a-society/qotw0502-2/', '2021-05-02T12:00:00Z', '2021-05-02T12:00:00Z'),
  ('l7355', 'what-is-the-effect-of-language-on-a-society', 'lisa-l', 'name', null, array['SOCIETY AND LANGUAGE', 'Society refers to a group of individuals bound by a set of relationships, whether functional or personal, public or private, they generally involve a balance of language.', 'Within groups, social and language can be interpreted in many situations, ranging from chatter to speech or from advertising pamphlets to literary novels. It is true that the faculty of language is linked to various cerebral centres that command the different organs, but all these centres control only parts of the language, because the synthesis only takes place at the social level of exchange, learning and actual practice of the language. Language is therefore a social function, made possible by biological functioning.', 'Omnipresent in society, it is elaborated, preserved and modified by social interactions, and constitutes an integral part of collective representations. In the same way, society is conditioned by language, since social communication determines the daily conduct of its members and constitutes the main point of social organization. Language is therefore a social phenomenon which is the indispensable instrument of society and on which it acts continuously. Even if it is the founding phenomenon of society, it sometimes becomes a divisive factor, hence the need for an ethic of communication.', 'RELATIONSHIP AND QUESTIONING', 'The links between society and language are very close, it is even difficult to imagine one without the other. While animals have only the voice, human beings have language – some philosophers will say that it is to distinguish between the just and the unjust. Having notions like language and society are what makes a family, a homeland.', 'The relationship between these two notions is complex and has always been so for decades. Between theories and hypotheses, many intellectuals have asked themselves questions about these existential subjects. For example, the Sapir-Whorf hypothesis tries to explain how language influences the world view. One could also ask the question of what comes first between society or language? Is your worldview influenced by your knowledge of the language or is your language influenced by the culture you live in? Indeed, we have the eternal debate of the chicken or the egg.', 'REAL-WORLD EXAMPLE', 'For example, there are many differences between languages in categorizing identical things, like river and river in English they are not identified in the same way as in French for example. For example, when in English we focus on the size of the river to determine if it is a river in France, we focus on the flow of the water to identify which river it will flow into afterwards. But is this due to the different geographical characteristics of each country or is it due to the way words have shaped the way these two peoples perceive water bodies differently?', 'It would seem that societal factors play a more than an obvious role in our way of speaking, there is one area to study it which is sociolinguistics. Age and gender are considered important factors that can have an impact on language use, but context and circumstances often determine what is or is not appropriate in a conversation.', 'Sometimes you may notice cultural differences when you are trying to understand your client, for example, and he uses one word rather than another to express a task and you would have used a different word to translate the same thing.', 'LANGUAGE DEFINES THE WAY OF THINKING', 'Scientists have conducted various studies on how language influences society, what people think and how they behave. Culture affects the way a person speaks and language is part of the culture.', 'An American behavioural economist asked whether a person’s ability to save is affected by language. He found that the language gap also shows economic differences. It would appear that people who do not strictly define time in their language, as is the case with Chinese, tend to save more than those who speak languages that distinguish between past, present, and future actions.', 'The way we interpret the things we feel and hear is influenced by personal experiences, norms, cultural rules, traditions and languages. Thoughts come from words and they initiate behaviour.', 'INTERNATIONAL LANGUAGES', 'International communication and global trade are also influenced by languages, to do business effectively in other countries the company must be able to convey messages to its employees and target customers in clear and understandable language. Indeed, all forms of communication must be translated into the local language so that the interpretation is clear. It is also important to adapt its employees to local and corporate culture. This training must be highly personalised according to the experience and culture of the people.', 'If you really understand a language and the differences it has, you will be better able to understand and discover clues about what constitutes correct and incorrect behaviour for the local culture.', 'LANGAGE ET COMPORTEMENTS
According to a scientific study, it seems that adults do not realize the impact of their words on children, the younger the child, the greater the effect. Indeed a very young child has no sense of time, denying him or her something could mean a protest through bad behaviour.', 'As the ability to express oneself in a language develops, the child’s behaviour improves.', 'A language is a communication tool, it is also very important for showing social behaviour. It is used to interact with the rest of the world and self-regulation of behaviour requires the presence of language. The child learns to use language to influence the behaviour of others and expresses feelings and emotions through language. These are the same rules that also apply to adults.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-the-effect-of-language-on-a-society/qotw0502/', '2021-05-02T12:00:00Z', '2021-05-02T12:00:00Z'),
  ('l7379', 'what-is-the-past', 'b-janszen', 'name', null, array['As I sat and thought about this question, I realized increasingly how unsure I was about my view. As I then turned to the all-knowing ‘Google,’ I realized that very few others had shed light on it either… Ironic, considering how much time we all spend dwelling in the ‘past’, that we would not have a clear theory on what the past actually is.', 'I think most people’s conception of past is that it somehow is moving backwards from the present. Alan Watts, however, introduced the metaphor of a ship and its wake – asserting that the past trailed off from the moment, but not quite as it may appear. The wake of a ship travels outwards and forwards, even while appearing to travel backwards. Perhaps this optical illusion is true of the past too – it is not a linear notion. When we remember ‘the past’, we do so through the lens of our own minds – in this moment – and subject to our own memories that have piled upon whatever the event ‘was’. This is pretty heady stuff, but makes sense if you really study your experience of ‘remembering a past event’. Thus, perhaps my theory is that the boat of awareness cuts through the ocean of universal consciousness, creating ripples and waves that trail outwards and forwards. That is what creates the choppy-ness of our memories – the turbulent waters caused by the ship’s wake.', 'Overall, the clearest understanding of the past comes when the turbulent waters begin to settle. Through mindfulness, meditation, quieting of the mind, etc, it becomes clear that the past is an extension of the ‘present’, the only thing there is. It branches off from here, now. If we insist that there is such a thing as ‘the past’, we must begin from the experience itself – here and now – rather than some philosophical babble such as what I’ve presented :).']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-past/qotw0509/', '2021-05-09T12:00:00Z', '2021-05-09T12:00:00Z'),
  ('l7403', 'reconnect-to-ancient-ways-or-embrace-a-technological-age', 'will-j', 'name', null, array['Technological progress is disruptive. New communications devices lead us to interact with each other differently. Developments in machinery and computing change how we work. The internet rewrites our consumer behaviors. All such innovations require us to relinquish ways of being with which we are familiar and comfortable in order to learn new practices.', 'Just as a technology disrupts what is established, so that technology is destined to itself be superseded. The technological world is a constant regeneration. Within this climate of inescapable technological upheaval, it is appropriate to consider how we manage the transitions that are imposed on us in our day-to-day lives. Stoic philosophy provides a suitable discussant for such considerations given its focus on how we respond to external or environmental circumstances.', 'Australia, the country from which I write, offers an interesting context for this kind of discussion. The topic of our relationship with technological change emerged in Australian politics when the federal minister, Malcolm Turnbull, successfully challenged for Australia’s prime ministership.', 'Turnbull proclaimed in his victory speech that the “Australia of the future has to be a nation that is agile, that is innovative, that is creative”. Developing the nation’s capacity to benefit from innovative technologies was part of Turnbull’s promise to “all Australians” that his leadership “recognises the opportunities of the future”.', 'Turnbull’s view was that these opportunities arise via the “disruptive effects” of technological development. The new prime minister accordingly implored the Australian population “to recognise that the disruption that we see driven by technology, the volatility and change, is our friend, is our friend if we are agile and smart enough to take advantage of it”.', 'This call to embrace change brings us to the Stoics. As we will review, ancient Stoicism regularly asserts that change is the world’s all-encompassing condition. For the Stoics we are living rationally if we can understand that the changes that occur in our daily lives simply reflect the world’s default state.', 'Rationality not only underpins our appreciation of a changing world. It is also the very constitution of that changing world. Yes, the Stoic world itself is rational. Our rational appreciation of a changing world hence acts as a trace of that rational world. This is a counterintuitive notion. Rationality is typically something we attribute to thinking humans. How can the entire world be rational?', 'Sextus Empiricus reports that Stoicism from its first formal eras answers this question by describing how God’s rationality pervades the entire world to varying degrees. Because this world changes, change must be rational. As Anthony Long and David Sedley translate in their The Hellenistic Philosophers, Sextus’ account is that “what exists” in the world for the Stoics is “set in motion” by God’s reason. This reason is present everywhere in the structuring of the world and “guides it in due order into generations and changes”.', 'The later Stoic Epictetus guides this recognition of universal change into a series of mantras designed to help us to accept the inescapably changeable nature of our world. Turnbull earlier defines change as beneficial to our lives if we can appreciate its inevitability. On this point he might cohere with Epictetus when the Stoic posits that our life will be smoother once our mind accepts the certainty of change. As we find in one of Epictetus’ fragments:', 'The nature of the universe was, is and always will be the same, and things cannot happen any differently than they do now. It’s not just mankind and the other animals on earth that share in the cycle of change, but also the heavens and even the four basic elements…If we try to adapt our mind to the regular sequence of changes and accept the inevitable with good grace, our life will proceed quite smoothly and harmoniously.', 'Marcus Aurelius follows with a further emphatic directive to live with change rather than to fight it. In Meditations Marcus posits that because the “order of the universe” is preserved by its changes there is “nothing fearful about them” (2.17). If we are ever anxious about the changes imposed on us Marcus advises to “bring to mind all that you yourself have already seen changed” (4.3). Even more comprehensively he states that if “someone is afraid of change” they should reflect on how absolutely nothing “can ever come to be without change” (7.18).', 'There is a certain symmetry here with Turnbull’s position. Turnbull recognises the fear that technological change instils. It is daunting to have to learn new practices in order to be able to participate in society. Such change can furthermore jeopardize the ongoing existence of our jobs. Change threatens the current control we think we have over our lives.', 'While being receptive to these concerns, Turnbull also acknowledges that everything is transitory in our world. We must accept that change, often portrayed as progress, inescapably defines our existence. Marcus likewise recognises a world in perpetual flux. Our acceptance of such flux requires contextualizing any particular or localized change within “a constant succession of change…scarcely anything stands still” (5.23).', 'Despite this basic consistency between the two, we must also be sensitive to crucial differences between the Stoic sense of change and Turnbull’s position. The first point in this regard concerns how the Australian prime minister identifies change as something we can “take advantage of”. Embedded within this orientation is the imperative that we can take advantage of change for our own material (commercial) gain.', 'The Stoics conversely are less concerned with the material benefits of recognizing change as our inevitable condition. They are instead motivated by how accepting a changing world helps us to live rationally.', 'Certainly for the Stoics some material benefits will arise from living rationally. Stoicism refers to such benefits as “preferred indifferents”. Often a preferred indifferent comprises material goods (enough money to buy food, for example) that a Stoic would prefer to live with, than live without. If such goods arise through our rational existence it could indeed be irrational to discard or ignore them.', 'Primarily though the Stoics maintain an indifference to such goods and benefits. Change itself is accordingly never harmful in Stoicism, even if it might mean we lose these material goods. For Turnbull the fear is that if we do not accept the reality of change and take advantage of it, we will lose the associated material benefits. Conversely as Marcus asserts, what is harmful for a Stoic is fearing change itself, because such fear irrationally contradicts that the world’s nature is change (4.39).', 'Appreciating this difference refines our sense of the Stoic impulse regarding change. From this we can attend to a more dramatic diversion between the Stoics’ and Turnbull’s respective claims around change — in particular technological change. Doing so will help us to evaluate our own Stoic relationships with technology.', 'Technology, Wisdom, and Subjectivity', 'An era of widespread technological advancement and associated opportunities represents for Turnbull an unsurpassed state of satisfaction with life for current Australians. In comparing the present era to previous periods in Australia’s history, he declares:', 'There has never been a more exciting time to be alive than today and there has never been a more exciting time to be an Australian (Turnbull 2015).', 'Turnbull specifically attributes this peerless state to how highly engaged present-day Australians supposedly are with the innovative opportunities that his government can facilitate. Technological developments are not simply destabilizing. They produce a generation of Australians more fulfilled by their world than ever before.', 'By shifting our Stoic lens to Seneca (the Younger) we can differentiate a Stoic view on our relationship with technology. Contrary to Turnbull’s position, in one of a series of letters to Lucilius (a highly ranked public official in Sicily) Seneca opposes technological advancement from our most elevated or fulfilled subjective states.', 'We must contextualize Seneca’s position by firstly appreciating his concerns with a preceding assertion from the Stoic Posidonius. Seneca tells us that Posidonius correlates technological development with the wisdom of philosophy in positing that “philosophy invented the technologies we use in daily life” (90.7). It is philosophy, in the Posidonian view, that developed for example the “modern engineering” techniques and intelligences which produce buildings and cities.', 'An issue in equating philosophy with engineering in this manner for Seneca is that the “towering buildings” that such technologies design are a “danger to their inhabitants” (90.8). Rudimentarily this danger concerns the potential that the physical infrastructure could fail and fall on us. Philosophy conversely would never fail us.', 'This insight leads us to how for Seneca a more complex threat emerges where the comforts of modern technologies affect our rational appreciation of life. With newly elaborate housing, and technologically valuable possessions, a desire overcomes us to harbor what we own under the complementary technologies of “lock and key”. We become individually obligated to protect goods of perceived material worth from the rest of the community.', 'This turn is detrimental to our wellbeing in Seneca’s view. We are in effect slaves to the things that technologies produce. Indeed through technology we increasingly and irrationally depend on material externals. In an era of technological advancement, what “dwells under marble and gold is servitude” (90.10).', 'Seneca distinguishes this time from the period that preceded technological progress. There he believes the human approach to live in open, thatched houses “let them be free” (90.10). Seneca’s differentiation from Turnbull’s present-day position is readily apparent. The most technologically advanced generations do not experience a most subjectively fulfilling existence. Quite emphatically for Seneca rather, “the era that preceded was truly happy” (90.9).', 'You might be asking yourself in response to Seneca’s interventions though; doesn’t technological innovation indicate that we are becoming more intelligent? Surely in our technologies we illustrate that as a species we collectively understand our world better? Technology after all is not just bound up in the engineering of city buildings and the production of smartphones but is also responsible for furthering medical research.', 'We might in this way typically correlate technological advancement with our wisdom and intelligence. Not Seneca. In his view all our technologies, whether they build cities, design quicker modes of transport, or keep us healthy and well-fed via better farming equipment, were “discovered not by wisdom but by human ingenuity” (90.11). We might deploy reason in producing such new goods and techniques. For Seneca nevertheless our wisest states come from a rational existence that is not bound up in crafts but is “unencumbered by as much as possible” of the material world (90.13–16).', 'Seneca is not here proposing that we intentionally become materially destitute. He would not think it rational to live entirely free of supports for our existence. Elsewhere in his letters to Lucilius he in fact discusses how it can sometimes require more rationality to live with wealth and not be adversely affected by it than to live without wealth (20.10).', 'The point for Seneca is instead that we have been designed in a way that nature has already assigned us with everything we need to live rationally and therefore happily. The goods that arise from our “numerous technical skills” (90.18) do not condition our most fulfilled subjective states. To the contrary, such materialities can detach us from a rationalized existence.', 'If such technological advancements are not intrinsic to our rationality they are not internal to wisdom. Certainly, technologies develop products that seem to exhibit our species’ growing intelligence. Seneca reports that this is Posidonius’ view, for whom intricate weaving technologies or enhanced agricultural techniques must have been “invented by the wise” (90.20–21). Even travel technologies that were allowing the ancients to cross seas more quickly and comfortably must have come from the wisdom of a sage for Posidonius (90.24).', 'Seneca retorts though that “wisdom occupies a loftier seat” than that which “trains the hand” to engineer technological and technical advancements (90.26). Wisdom serves a rational existence. It is not associated with the triviality of artificial supplements that might make life more temporarily exciting.', 'Posidonius is not oblivious to this distinction. As a Stoic he is fundamentally still committed to prioritizing rational life. Posidonius consequently anticipates the kind of critique that Seneca presents by qualifying his overall position with the notion that the sage, the bearer of ultimate wisdom, will be able to “detach from technology” (90.30).', 'Seneca criticizes this caveat too. He does this by arguing that no sage ever “went near” technology to begin with. Seneca here invokes the transience of technological developments, which might remind us of my opening characterization of current technological intervention. Because technologies that are introduced are soon superseded, for Seneca a sage would know that it is not wise to “take up anything that had to be subsequently laid aside” (90.30). A rational existence conversely is timeless.', 'The transience of material technologies for Seneca might in part be attributable to the earlier noted individualized outcomes that they serve. The newest houses in Seneca’s era featured securities that enabled people to hold possessions and resources away from their communities. Individual outcomes come and go with the individuals who benefit from them. They otherwise serve no one.', 'Contrary to this, for Seneca there is not a “better condition for the human race” than the time when we all shared in a common nature that “provided for the maintenance of everyone” (90.38). Everyone is wealthy in this mode. Wealth here refers to a shared rationality rather than to mundane material things and contradicts a technologically advanced era in which people must protect their goods. He consequently describes how this latter existence comprises an irrational separation from a pantheistic, unified world and means that “you moderns…tremble at every sound your houses make” (90.43).', 'Does this mean that Stoicism requires us to be anti-technology? In a word, no. I can illustrate why via a trend in current scholarship, which reconfigures the underpinning condition of a Stoic pantheistic universe.', 'Are the Stoics Anti-Technology?', 'Our earlier discussion presented the Stoic idea that God’s rationality conditions the entire universe. God is everywhere. His rationality orders a physical world. It is even apparent in our own rational natures.', 'Certain recent Stoic perspectives however are motivated to replace these divine conditions. Within this contemporary re-orientation, consistencies emerge between Stoicism and the knowledges that technologies facilitate — in particular scientific technologies.', 'Lawrence Becker’s A New Stoicism provides an influential version of this motivation. In one regard Becker recognizes the importance of maintaining the core feature of the ancient Stoic impression of the universe. He duly argues that it would not be right to dismiss Stoicism’s logocentrism. This logos is the active principle that animates the world. As we have seen, for the Stoics this active principle is God’s reason.', 'Becker also wants to shift our understanding of this active principle however away from God’s divinity. His intervention is to instead conceive of this principle as more scientifically grounded. The consequent suggestion is to replace the Stoic maxim of living according to a divine rational nature with the imperative to instead live according to “facts”. One source of such facts is, in Becker’s view, experimental science.', 'This mandate actually coheres with ancient Stoic assertions around the rational daily practice of accepting a changing universe and determining what is, versus is not, in our control. Sudden localized misfortunes that we experience for example can be contextualized via a scientific appreciation of a causal universe’s perpetual transitions. “Contemporary cosmic science” for Becker helps us to recognize that the “universe is…in constant, tumultuous evolutionary change” and provides “humbling facts about our place” in the world (11).', 'Following Becker’s lead, Massimo Pigliucci and Gregory Lopez also recently posit in A Handbook for New Stoics that most “modern Stoics are not pantheists, but accept the contemporary scientific account of the world” (59). The suggestion from all such positions is that scientific technologies provide us with knowledges. If this knowledge assists us to appreciate the world rationally, then the scientific technologies behind them contribute to Stoic ways of being. Piotr Stankiewicz in an interview with Modern Stoicismagrees that:', 'Science teaches us how the world works and we, as Stoics, mustn’t oppose that. Thus, we will be happy to vaccinate our children. We won’t deny the Moon landing. Also, we will be eager to use iPhones, internet and whatever future technology comes about. In a word, going unscientific and anti-technological is also going unstoic.', 'From the preceding perspectives intersections hence emerge between (i) ancient Stoic impressions of universal change, (ii) modern views on technology, and (iii) the imperative to live rationally.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/reconnect-to-ancient-ways-or-embrace-a-technological-age/qotw0516-3/', '2021-05-16T12:00:00Z', '2021-05-16T12:00:00Z'),
  ('l7400', 'reconnect-to-ancient-ways-or-embrace-a-technological-age', 'paola-d', 'name', null, array['Artificial Intelligence, or AI, is a broad term used to define a wide range of advanced technologies and techniques aimed at creating intelligent and autonomous systems capable of reasoning, decision-making, and executing functions with limited, or without, human input and supervision.', 'There are many technical innovations, such as novel algorithms and programming techniques, to enable such capacities, potentially representing a new evolutionary step for humanity toward “higher cognition.”', 'On the one hand, intelligent technologies can contribute to progress and can help to overcome human limitations, for instance by exponentially increasing our computational abilities—the ability to analyze and process vast amount of data with great precision—and enhance human cognition in many ways. We should, however, be aware that these intelligent technologies come with a new range of errors and risks that could potentially become a threat.', 'Recently, international communities, both technical and non technical, and both academic and civil, have been intensifying efforts to raise awareness of the risks that may arise from widespread AI technologies controling our systems. Yet, unless the human consciousness evolves alongside the new technical abilities, these efforts may not be sufficient to avert the risks.', 'Very interesting novel computer interaction protocols, which I broadly call “mind technologies,” aimed at enabling communication between human users and computers—not via keyboards or touch screens, but via inputs and commands given directly by the brain, are now being researched.', 'These novel interactions generally fall into two groups, either external EEG (electroencephalography) interfaces, where electrodes positioned on the head “read” certain types of brain activity, which is then translated into executable commands by software that interprets mental activity, or internal sensors that are implanted directed into the cortex.', 'Startup companies such as Neuralink have reportedly started researching technology in which electrodes implanted in the brain could be used to cure brain pathologies and, rather ambitiously, merge computers with brains so that humans could one day engage in “consensual telepathy.”', 'Elon Musk, founder of Neuralink, explains this possibility as follows: “There are a bunch of concepts in your head that then your brain has to try to compress into this incredibly low data rate called speech or typing. That’s what language is, your brain has executed a compression algorithm on thought, on concept transfer. If you have two brain interfaces, you could actually do an uncompressed direct conceptual communication with another person.” (Reuters)', 'But what would prevent the opposite from happening: that a super intelligent, evolving machine with high control capabilities uses the electrodes to disable all critical thinking abilities in the minds of humans?', 'In addition to this field of research, there is increased scientific interest in telepathy,* and encouraging scientific research findings on telepathy have been published by the research institute Starlab, French firm Axilum Robotics, and Harvard Medical School.', 'The main motivation and justification for experiments with various types of brainwave reading via EEG is that research in this field may one day provide a new communication pathway for patients who might not be able to speak.**', 'The justification for such research is that, in addition to medical benefits, brain-to-brain communication could find applications in the gaming and military domain. “Soldiers, for instance, could use the technology on the battlefield, sending commands and warnings to one another. Civilians might benefit as well; businesspeople could use it to send cues to partners during negotiations, or pitchers and catchers could avoid sign-stealing during baseball games.” (Smithsonian Magazine)', 'While technological progress is important, such mundane aspirations may be contradicting with the underlying principles of mind development. Excited at the prospect of scientific advances, researchers seem to ignore that enhanced cognition comes with enhanced responsibility, maturity, and responsible decision-making abilities.', 'New research frontiers can be hotbeds of (open-ended) questions. From a technical viewpoint, computer-based (coded) communication relies on explicit knowledge representation, formal languages, gestures, signs. When communication takes place directly, mostly from brain to brain but also from brain to computer, the knowledge is often not codified according to defined technical standards, but implicit and tacit. In an attempt to study and understand further aspects of how mind and consciousness support implicit and tacit knowledge and communication, science looks toward the world’s “wisdom traditions.”', 'Although not historically acknowledged by modern science and until now considered somewhat “a myth,” phenomena like mind-to-mind communication are well documented in certain Eastern schools of thought, among yogis and meditation practitioners.', 'If anything, scientific research into these claims, which are plentiful in the world’s wisdom traditions, is important to prove that they may not be unfounded after all.', 'Yogic systems and wisdom traditions are traditionally considered closer to philosophy and religion than to modern science, but they are finding their way in modern theories of cognition. The ancient Indian thought system Samkhya-Yoga, for example, has been an object of contemporary research aimed at bridging Western modern thought with ancient wisdom. This research is analyzing independently gathered empirical evidence and is leading to the conclusion that more comprehensive theories may be required to explain the breadth and depth of cognitive dynamics before we can even begin to grasp the complexity of consciousness in the context of reality and nature.', 'In the yogic and tantric Buddhist traditions, there are various references to mind transmissions in which two practitioners who are synced up to similar experiences can become synthonized (in tune with the same frequency).*** In these ancient systems, cognition is not isolated from other aspects of human experience and behavior as it is in mainstream Western psychology.', 'Examples of extraordinary cognition are knowledge of the past and future, clairvoyance, clairaudience, psychokinesis, and telepathy, which are generally the result of mind training and strict practices aimed at developing and strengthening control over one’s faculties and a deeper levels of consciousness. What modern technological advances need to consider is that the aim of obtaining extraordinary cognitions in these wisdom traditions is not killing, or winning wars or competitive games. In fact, it is the opposite: these extraordinary cognitions are, if at all real and possible, the outcome of mental refinement, of the development of compassion to reach liberation and enlightenment, and the attainment of pure consciousness and extinguishing one’s karma.', 'One of the important practices taught by the Buddha to control the mind and ensure it does not go astray, described in the Dhammapada, is to “avoid all forms of destructive actions, engage in actions which are positive and beneficial, and tame your mind, and this, in essence, is my way.”', 'In developing powerful technologies capable not only of autonomous intelligent behavior, but also of communicating directly with the brain and human consciousness, system developers should familiarize themselves with the yogic and Buddhist traditions where such capabilities are/were obtained as the result of mind training and related practices. Even more important is to understand that the purpose for advancing technology is not winning on the battlefield or in a sports game, but to gain enlightenment and liberation from suffering for all sentient beings, that is to develop spiritual awareness and altruism. Higher cognition without bodhicitta will always carry implicit and inherent unavoidable risks.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/reconnect-to-ancient-ways-or-embrace-a-technological-age/qotw0516-2/', '2021-05-16T12:00:00Z', '2021-05-16T12:00:00Z'),
  ('l7396', 'reconnect-to-ancient-ways-or-embrace-a-technological-age', 'cnscsns', 'name', null, array['To answer this, we must recognize the power of human ingenuity throughout our species’ history. We have been using ‘technology’ since Homo sapiens emerged hundreds of thousands of years ago. Whether it be creating tools out of sticks and stones, calendars from astrological patterns, or computers, we have always embraced technology. This new phase of humankind is crossing over into yet another great leap forward in technology, which is both exciting and nerve-racking. All of this, however, is just to say that the question is not one or the other. The answer is that our future depends on how we recognize and integrate both of the above options. They are both interdependent and inseparable. Let me explain:', 'Where humans seem to have gone awry is that in our fog of immense progress in technology, we have lost our footing – our connection to the earth. We are becoming more and more ‘computerized’ – physically and in our consciousness. When we reflect on ‘ancient ways’, we see Shamanic cultures. Peoples whose existence was indelibly connected to the Earth and its processes. People whose technology, social structure, spirituality, and all-around lifestyles were reflective of and in harmony with the Earth. As more and more aspects of indigenous roots are cut, we lose more and more of our connection to the soil of human existence. Without these roots, even the beautiful flowers of modern and future technology cannot bloom and perhaps even, the whole plant of human society can die.', 'This is not to diminish the incredible beauty of modern technology. By itself, the technology we have been able to create in recent decades is among the most profound accomplishments in the known Universe. It surely represents our portal into the ‘unknown’ regions of our universe. However, like any teenager who is tasting freedom for the first time, we have shown an immaturity around harnessing this profound technology. We have lost our footing and, in the process, are carelessly and recklessly destroying the very ground we stand upon. Without the consciousness of ancient societies – that of connectedness, gratitude, compassion, and wisdom – all of our efforts and accomplishments technologically will only accelerate our destruction.', 'All in all, our next phase of evolution must be double-edged. It must be a form of expansion, encapsulating the ancient wisdom of our ancestors, our own intuitive wisdom, and the intelligence embodied by technology. This is our only path forward – any other way is only a path towards being lost.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/reconnect-to-ancient-ways-or-embrace-a-technological-age/qotw0516/', '2021-05-16T12:00:00Z', '2021-05-16T12:00:00Z'),
  ('l7426', 'what-is-the-mark-of-a-best-friend', 'mauricio-a', 'name', null, array['The term “BEST FRIENDS” has gotten a bit romanticized. But basically, a best friend is a person who cares about your well being. One who respects you and is willing to spend time (a major resource) to help you if you need it and be there for you both in the good and the bad times. Quantity spent together is in fact not a necessity. The reason why people say “the person who you spend time the most” is because they are using the misconception that spending a lot of time with people will automatically make you best friends with them. Which is not necessarily true, although it is not hard to assume that you might want to spend time with people who respect you.', 'The quality of connection can be very subjective and although time can be a somewhat safe factor, the real way to know is if the other person likes you is if they respect you. I have for example best friends that due to everyday life I do not see often (6 months or more) but I know that if I called (or if they called me) at 3:00am for help, we would be there for each other.', 'It has been said before that “a best friend” is a relationship without the romantic love.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-mark-of-a-best-friend/qotw0523-3/', '2021-05-23T12:00:00Z', '2021-05-23T12:00:00Z'),
  ('l7422', 'what-is-the-mark-of-a-best-friend', 'shoshana-f', 'name', null, array['Who would we be without our friends? From an early age, friends teach us the ropes, giving us the building blocks to learn how to give, love and face life’s ups and downs. The United Nations recognizes the importance of friendship and proclaimed July 30 as International Friendship Day, highlighting friendships as a way to bridge differences and bring about more peace in the world. Take a moment to celebrate your friends both near and far by exploring the eight defining characteristics of what being and having a best friend really means.', '1. TELEPATHY', 'Your best friend has the uncanny ability to read your mind before the words pop out of your mouth. Just by exchanging a glance, you both know exactly what the other is thinking.', '2. HONESTY', 'Whether you have a piece of broccoli stuck in your teeth or you are about to embark on a major life decision, your best friend is there to give you their real opinion. While sometimes it can seem a bit harsh or they may even disagree with your choices, your best friend won’t hide their views – especially if they think it’s in your best interest.', '3. HUMOR', 'Rolling on the floor laughing till your stomach hurts doesn’t happen with just anyone. Best friends know exactly what will trigger a belly-aching laugh, and between the personal jokes and shared experiences, your bestie knows how to tickle your funny bone.', 'Your best friend thinks you’re hilarious. (CREATISTA /Shutterstock.com)', '4. EMPATHY', 'Your best friend can actually feel what you are going through – because they have been there before. Or, they simply relate to you on such a deep level that they can profoundly understand what you are experiencing.', '5. GENEROSITY', 'Giving is something that comes naturally between best friends, with each person willing to share what they have with the other. A true friendship has boundaries, but abundance is key. No tabs are kept on who gives and who receives, creating a flow of sharing and caring between you both.', '6. TRUST', 'Secrets, fears and deep thoughts are just some of the things you freely share with your best friend – because you know that what you say remains in the vault. Your best friend would never use your private information against you or to hurt you in any way.', 'One of the people you trust most in your life. (Ilike / Shutterstock.com)', '7. ENCOURAGEMENT', 'Your bestie thinks that you are awesome and is there to give you a boost when you are feeling low. As your personal cheerleader, your best friend reminds you of how many great things you have to offer the world, always focusing on your positive attributes that make you shine.', '8. STEADFASTNESS', 'Your best friend has your back! No matter the situation, you know that when you need your friend to be there for you, they are present without fail. As James Taylor and Carole King sing:', 'You just call out my name
And you know wherever I am
I’ll come running to see you again
Winter, spring, summer or fall
All you have to do is call
And I’ll be there
Yes I will
You’ve got a friend…']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-the-mark-of-a-best-friend/qotw0523-2/', '2021-05-23T12:00:00Z', '2021-05-23T12:00:00Z'),
  ('l7419', 'what-is-the-mark-of-a-best-friend', 'barton-g', 'name', null, array['When we are young, we seem to have no shortage of “best friends.” As we mature, however, the nature of our friendships changes. Having or being a best friend is no longer as simple as labeling someone our BFF and having them reciprocate.', 'Other more important factors come into play, including:', '• Being emotionally supportive. This is probably the most important element of any adult friendship. Best friends refrain from unnecessarily criticizing each other and tend to be nonjudgmental.', '• A best friend will listen to you and thoughtfully respond rather than react to what you’ve said even if you have triggered something in him or her. The ability to hear what another is truly saying is one of the best parts of friendship.', '• Best friends go out of their way for the people they care about, and it feels good to both parties. You can tell who your real friends are when you need help with a move or a ride to the airport.', '• Thoughtfulness is a quality that deepens and strengthens any friendship. Being able to see someone else’s needs—and to do what you can to fulfill those needs—enables bonding experiences. Our best friends do things for us no one else would think of.', '• Reliability. When you know you can call on your best friend to bail you out of a jam, 24/7, it makes you feel better and increases your overall confidence.', '• Best friends accept you and all your flaws. They don’t expect perfection. When you aren’t at your best, they are understanding rather than critical. If you’re having a bad day, someone who cares for you will ask if they can help or if they should let you be alone if that’s what you need.', '• A friend once gave me a cocktail napkin that said, “Friends are therapists you can drink with.” A good friendship is indeed therapeutic, though a good friend is not the same as a drinking buddy.', '• A strong friendship defines you both and helps each of you navigate this thing called life. Your friend is a mirror who reflects back to you who you are to them. In other words, your best qualities shine, and those pieces that need improvement are not judged but understood.', '• It’s hard for some of us to cry alone. Instead, we might need a shoulder to cry on, and having a friend you feel comfortable doing that with is a gift. When facing difficulty, having someone you can really let your pain out with can be invaluable.', '• Best friends have your back. Knowing you can trust another person with your well-being allows you both to explore and enjoy more new things than you would on your own.', 'It’s life-affirming to have a best friend to help pull you up but never put you down. You have to be willing to give as much as you want to get, but I don’t know anyone who thinks a good friendship is not worth the effort.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-the-mark-of-a-best-friend/qotw0523/', '2021-05-23T12:00:00Z', '2021-05-23T12:00:00Z'),
  ('l7450', 'to-what-extent-do-highs-lead-us-to-truth', 'shay-p', 'name', null, array['For the ‘average’ being, ‘highs’ represent a temporary refuge – an escape from the sometimes overwhelming ocean of suffering most of us swim in. We swim in suffering because of a fundamental ignorance about our reality – a mistaken separation between self and other. Stemming from this ignorance, we project our desires upon what we deem as ‘other’ (people, things, experiences), and become accustomed to a life centered around the ebbing and flowing of desires being created and fulfilled. Yet our contentment is much like that of scratching an itch – temporary relief, but not lasting. So for those of us existing this way, our ‘highs’ are moments in time when the itch has been scratched and there is temporarily no ‘desire’. They’re the driftwood that lets us rest in the turbulent seas. They’re all we have (at least all we think we have). So why not indulge?']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/to-what-extent-do-highs-lead-us-to-truth/to-what-extent-do-highs-lead-us-to-truth-2/', '2021-06-02T12:00:00Z', '2021-06-02T12:00:00Z'),
  ('l7448', 'to-what-extent-do-highs-lead-us-to-truth', 'cnscsns', 'name', null, array['The great irony is that our confused state of typical waking consciousness does not recognize ‘truth’ and thus mistakes itself for its ignorant understanding of truth. In reality, our ‘highs’ are truth – they are temporary moments of merging with the divine, free of the distraction of our everyday, conditioned consciousness. When we are drunk, high, in the zone on the sports field, with loved ones, deep in stimulating conversation, in nature, etc – all of these experiences are examples of moments of ‘unity’ – moments of truth. The only thing that’s separating us from this unity in all our waking moments is a conditioned mind of dualism and separation. So rather than our ‘highs’ leading us to truth, it’s everything-other-than-our-highs leading us away from truth.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/to-what-extent-do-highs-lead-us-to-truth/to-what-extent-do-highs-lead-us-to-truth/', '2021-06-02T12:00:00Z', '2021-06-02T12:00:00Z'),
  ('l7446', 'to-what-extent-do-highs-lead-us-to-truth', 'chan-lee', 'name', null, array['These ‘high’ moments should not be disregarded in the game of truth, nor should they be sought after and mistaken for ‘truth’ itself. There is a middle ground here, which recognizes ‘highs’ as both expository, fun, and interesting, and ALSO transient, impermanent, and full of suffering. Whether we speak of ‘high’ in connection to a substance, or from our own volition is not the main issue. There is often truth embedded in these transitory ‘highs’ – whether that be the shining through of our potential, a moment of un-debilitated bliss, or an epiphany of some kind (or something else altogether). However, given the fleeting nature of these experiences, they are more ‘fingers pointing to the moon, than they are the moon itself’ – to steal a zen phrase. As long as we have the wisdom to enter these spaces recognizing this fact, we can gain tremendous benefit from them. However, like any delicious meal, without the wisdom to know when it has filled us successfully, we will keep consuming until we are sick.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/to-what-extent-do-highs-lead-us-to-truth/to-what-extent-do-our-highs-lead-us-to-truth/', '2021-06-02T12:00:00Z', '2021-06-02T12:00:00Z'),
  ('l7479', 'should-you-be-doing-more', 'chan-lee', 'name', null, array['I venture to say that we should all be ‘doing more’. Perhaps this is a turn-off, but I firmly believe that it is true. Doing ‘more’ – not in the sense of getting more work done, but of doing more of what’s truly important. For each of us, this is slightly different, but basically under the same few umbrellas. I believe these umbrellas are that we each want happiness and to minimize our suffering, we all want a healthier society and planet, and we all want to feel like we made the most of our precious lives. I prefer to stay away from generalizations, but if we honestly reflect on our lives, how many of us are truly doing what we can to satisfy these big three desires? Everyday experiences, such as boredom, afflictive emotions, meaningless work, numbness, and countless distractions of all kinds, all dominate our waking hours. Are these really the ‘best’ use of our lives?']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/should-you-be-doing-more/should-you-be-doing-more/', '2021-06-09T12:00:00Z', '2021-06-09T12:00:00Z'),
  ('l7474', 'should-you-be-doing-more', 'katy-c', 'name', null, array['You’ve spent eight or nine hours at your desk, except for a quick break for lunch. You’ve made progress. It’s been a good day. So why do you feel you should be doing more? This anxious feeling – that we’re never doing enough – where does it come from? Is it a modern affliction? One brought on by social media and screen-scrolling? Or is freelancing to blame? The constant need to push ahead from the fear of being left behind?', 'I never used to feel this way. Back in the days of “employment”, I’d have strict boundaries on when work began and when it finished. When I left the office, I went home, and that was that. I mentally pulled a curtain down on my job and relaxed, cherishing my evenings and weekends. (Mind you, Instagram wasn’t around back then, so that probably helped.)', 'But being a business owner is different. I make my own rules. Set my hours. Decide what’s what. Unfortunately, that can mean an unhealthy work schedule. One that probably begins on my smartphone as I switch off my morning alarm and sadly ends just before I pass out each night.', 'As someone who grew and (deliberately) downsized a PR agency and built an online magazine, it’s not surprising that I get anxious and feel I’m never doing enough. All of the emails I get these days from people asking for help – it’s lovely to be in that position but also daunting. Plus with so much competition out there, I understand that if I’m not pushing on, someone younger with more energy might overtake me.', 'Anxious thoughts aside, at the beginning of 2019, I vowed to make some serious lifestyle changes that would effectively make my life better. Building back my confidence was one primary focus. Getting a decent work/life balance was another. On the latter, I’m still working on it, but I’m getting there. Here, I will share what’s worked for me so far.', 'Get organised for mental clarity and calm', 'I start each day with a to-do list that’s realistic, adding one big job and a few small ones. I get the larger job out the way first, as this will take up the most energy and time. Then I roll my sleeves up and tackle the rest. By sorting everything planned, I feel in control. I know where I am with things. I can close the door on “work” and say hello to “play”.', 'I use Things to keep track of tasks. It’s in the cloud so syncs with my Mac and mobile, making everything more manageable. Before I switch off my computer at the end of each day, I like to go through upcoming tasks and add anything I might need to consider in future. Call it a “brain dump”, if you will. A mental cleanse.', 'By ticking things off my list, l feel amazing – as though I’ve accomplished something. By keeping track of what’s next, I don’t even think about work during downtime. I also always remind myself that I can only do so much.', 'Consider what the “more” actually is', 'When I’ve had a productive day, and I’m trying to wind down for the evening, if I still get that niggling feeling that I should be doing more, I sift through the mental noise and figure out what more actually is.', 'It could be a job I’ve been putting off. In which case, I grab a notepad and start to write a plan of action to address the next day. Or it might be something that’s building up – for example, emails to Creative Boom (and there are so many of them) get organised into different folders to tackle on quieter days. It could be something else I’m anxious about – have I done enough marketing this week? Should I write a blog post? What about another tips article?', 'Face up to the “more” and make a plan to address it. If it’s not so logical – if you can’t pinpoint what “more” is – then practice a little mindfulness through meditation, exercise or even ironing to alleviate any stress or unexplained anxiety.', 'Recognise the self-inflicted pressure and release the valve', 'If you work for yourself, there’s an enormous pressure to make, create, improve, see and do. It’s never-ending. It’s only made worse by scrolling through our Instagram feeds or browsing blogs and magazines that bombard us with the usual “hustle” rhetoric. (I know I’ve been guilty of this in the past – a bit of a grey area, as a lot of Creative Boom’s success, can be attributed to hard work and sacrifice.)', 'We’re so petrified we’ll get left behind, or work will stop coming in, we daren’t stop. We keep running on our self-made treadmills. And now we’re all exhausted by it. You can see just how much on Twitter. Mental health is a trending topic. People are opening up, admitting they can’t cope. (Revelation: we can’t keep running!)', 'But all that pressure, along with high expectations, is self-inflicted. No one is to blame but ourselves. That’s the truth. It’s a reality we must recognise. I’m certainly trying to.', 'I’ve asked myself the question lately, who am I trying to impress? It’s a question we should all ask. Why the pressure? If it’s fear of work drying up, that’s only natural. But if work is fine, clients are happy, and bills are more than covered, why aren’t we chilling out?', 'Take a moment to ask yourself honestly, does any of it matter? For instance, if you didn’t post something on Instagram today, would everything be ok? Could the side project take a break this evening, for a change? How about switching off entirely and taking a day off? Take a deep breath and relax. The world will continue to spin without you chained to your desk.', 'Meanwhile, if you’re feeling guilty about “doing nothing”, remember that you’re no good to anyone if you don’t take some time off. Rest is important. You have to recharge your batteries to be productive at work. I know this only too well, having experienced burnout first-hand and then not being able to handle anything. Prioritise your health and wellbeing.', 'If you’re feeling especially rough, avoid inspiration from others', 'Yes, that’s right. Get off Creative Boom, and It’s Nice That. Temporarily delete Instagram from your smartphone. Hide the smartphone – shove it down the sofa. Don’t go to creative talks to hear from people you admire or who run successful design agencies. Yes, really. Hide for a little while.', '(I went to a creative conference last year and the general mood from some other freelancers was sombre. Many felt overwhelmed by hearing from such inspirational speakers. “How will I ever be good enough?” was the theme of conversation. It was as though a dreaded cloud had fallen upon an anxious audience.)', 'Give your brain some breathing space. Be alone and ignore everyone else to stop the endless comparison. You’ll find your anxiety starts to lift when you’re not constantly being bombarded by “greatness”.', 'In the words of Pablo Picasso, “Without great solitude no serious work is possible.”', 'Avoid comparing yourself to others', 'It’s easy to fall into the trap of comparing yourself to your competition, but it’s a genuinely fruitless exercise. What they’re doing has no relation to your business whatsoever. They are on a personal journey of highs and lows, mistakes and lessons. It’s unlikely that you’ll gain success by copying them because you won’t have been through the process yourself.', 'You have to focus on your strengths. The very essence of what makes you unique. Creative Boom, for instance, has gone through many changes over the last ten years. I’ve made a lot of mistakes and learnt a lot of lessons. But it’s always been what works best for me and my audience.', 'When people come to me and say, “I want to start an online magazine like you, how can I make it a success?” I shrug my shoulders and say, “Honestly, you’re on your own path, and only you know what’s best.” It’s the truth. Ten years of doing this and I’m not sure I’d know where to start with advice on running a magazine – any tips I’d offer would probably become outdated rather quickly.', 'Redefine success', 'Speaking of success, what does success mean to you? Is it money related? Will you feel happy once your business hits a particular turnover mark or size? Or is it about the car you drive or the house you own? Is “success” about wealth, happiness or both? What are you striving for?', 'It sounds ridiculous to ask this question but have you ever stopped to consider where you’re heading?', 'For me, I always had a vague idea of what I wanted from life. I knew I wanted to be a journalist. That was pretty clear. I knew that I wanted to be happy and see the world. I’m not sure money was ever a priority, but I wanted enough to be safe. But I’ve never really stopped to think what next? It’s all been somewhat sporadic. None of it planned.', 'As for the very meaning of success – for me, that’s a tricky one. Its definition hasn’t changed as I’ve got older. I just wanted to be happy. That’s it. Nothing more. To do something I loved for a living and smile a lot.', 'I think I’ve always remembered that. But, like many, have fallen into the trap of overwork and the need to achieve more, more, more. That’s just the circle I’ve found myself in.', 'Now I’ve turned 40; I realise that “work”, although still relevant, is no longer the main priority. Instead, I’m seeing that having more “time” is the ultimate goal.', 'That means I’m learning to say “no” more. I’m deliberately turning things down to become less busy and gain more time to focus on other pursuits. It’s been a slow process, but I’m much happier.', 'Work is just one aspect of our lives; it shouldn’t be the only thing we’re passionate about. To me, success means covering your bills, having a decent work/life balance and following your passions. It means being healthy and appreciating each day. What does success mean to you? You might find you’ve been prioritising the wrong things.', 'Enjoy the journey as well as the destination', 'Do you know those people who hate travelling? I’m not one of them. I love the process of packing my suitcase, going through security at the airport and settling down in my seat to look out the window and watch the clouds float by. I love the anticipation of the upcoming holiday. I get butterflies.', 'This probably comes from my lucky childhood. Both my parents worked incredibly hard to give me and my brother a wonderful life. But once a year, for two glorious weeks, we would drive to the south of France for a holiday.', 'Before we even got there, it was special. My mother had such a gift in creating magic out of the mundane; she would get us all excited about the whole journey. The night before the “big drive south”, my father would pack the boot of our car like some military operation. We were under strict instruction not to disturb him, as he had a “system” that he would religiously follow. He knew how to pack that car better than anyone, so we left him to it. But weirdly, you could see he enjoyed it. (I, too, have picked up this strange habit.)', 'And then we were off. The hovercraft or ferry was an adventure. Spotting the French car number plates and figuring out where they were from – that was fun. Watching the countryside flash past. The anticipation of what our accommodation might be like. It was all wonderful.', 'You can see what I’m getting at here – rather than focus on the actualoutcome, enjoy the process. Work isn’t just about results; it’s about the journey we take to get there. Savour it. Enjoy the little “wins” along the way. And understand that things don’t happen overnight.', 'Celebrate your achievements, no matter how small', 'Instead of focusing on what happens next, take a moment to celebrate how far you’ve already come. I’m doing exactly that this summer, as Creative Boom is celebrating ten years of supporting the creative community. And let me tell you, I didn’t even think about marking the occasion until a friend said I should.', 'Like a good old Brit, I thought, well, I don’t want to show off. And really, it’s no big deal. But I’m discrediting all the hard work and love that has gone into this “side project” over a decade of my life. There is, indeed, so much to celebrate. And celebrate it, I shall.', 'I’ve got some announcements to make next month on our 10th-anniversary. Until then, know this – we should all recognise our successes and wins. No matter how small. We don’t do it enough.', 'So next time you’re thinking about all the things you should be getting on with, sit back and recognise what has already come to pass. You’re doing great. Be proud of yourself and all you’ve achieved. You have so much to celebrate.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/should-you-be-doing-more/qotw0607-2-2-2/', '2021-06-09T12:00:00Z', '2021-06-09T12:00:00Z'),
  ('l7468', 'should-you-be-doing-more', 'jari-r', 'name', null, array['In today’s society, we are conditioned to think that we should be busier, do more and work harder. Many motivational speakers and success guru’s shout out well-meant (but plain wrong) advice that leads you to believe that you don’t do enough, and that’s why you’re not successful.', 'However, the notion that ‘doing more = achieving more’ is not nearly as effective as it sounds. In fact, I’ve experienced that doing less has helped me to achieve more. It took me a few years to fully realize this, as I (just like everybody else) have been conditioned to think that I should always be doing more.', 'Yet, by forcing yourself to go for less, you paradoxically end up with more. I know it may sound counterintuitive, but hear me out…', 'By setting limitations on your work and forcing yourself to do less, you need to focus on the essentials and you’re forced to drop the non-important. This is probably the biggest shift you can ever make in your productivity levels.', 'You need to make the most of your time by focusing on the most important things, instead of everything.', 'Only A Few Things Truly Matter', 'In reality, only just a few tasks truly matter. In any business, project or goal, there are merely a handful of tasks that significantly move the needle. All the other tasks are just ‘nice’ to do but are actually distractions for your most important tasks. ‘Nice’ isn’t worth your valuable time and energy. Only the most important tasks are worthy of that.', '“My goal is no longer to get more done, but rather to have less to do.”', '— Francine Jay', 'They key is to focus on that what’s essential and train yourself to drop everything else. That’s when you become highly productive and accelerate your path to success.', 'The 80/20 Rule', 'The phenomenon that there are merely a handful of mission-critical tasks comes from the 80/20 Rule. In short, the 80/20 rule states that 20% of inputs are responsible for roughly 80% of outcomes. In other words, about 20% of your tasks and activities are actually responsible for 80% of your desired outcomes.', 'This means that just a few things truly matter.', 'If you want to succeed, you need to focus the biggest majority (75% — 90%) of your time and energy on those tasks that are actually essential. By choosing the essentials, you make the greatest impact with just the minimal amount of resources spent.', 'Why Doing More Doesn’t Work', 'Real productivity is not about doing more, working harder or doing any task more efficiently. Rather, real productivity is about ruthlessly identifying what’s important, protecting your valuable time for those tasks and doing them as efficiently as possible.', '“Productivity isn’t about being a workhorse, keeping busy or burning the midnight oil… It’s more about priorities, planning and fiercely protecting your time.”', '— Margarita Tartakovsky', 'Unfortunately, way too many people are still focused on quantity over quality. They focus too much on the number of tasks they accomplish and the number of hours they work (quantity) instead of looking at the actual value they produce in a given day (quality).', 'Listen, it really doesn’t matter how much you do if you don’t create any real value with those tasks. In fact, it’s a lot more productive to work on only 1–3 important tasks that actually create a lot of value for you, your business or your customers, instead of trying to accomplish 23 mid- to low-value tasks each day.', 'Remember, it doesn’t really matter how many hours you work or how many things you get done. The only thing that matters is the value you create. That should become your measurement of productivity.', 'The truth is, when you have too many tasks to work on, you’ll take away valuable time, energy and focus from those tasks that actually move the needle. Your most important tasks don’t get the attention they deserve (and require) when you have too many other things to work on. The unimportant stuff gets in the way of the important stuff — and that’s productivity and success killer numero uno', 'Furthermore, spending time on the unimportant stuff will often only lead to incremental progress (or no progress at all), while the important stuff leads to significant progress. It’s obvious which of these two should deserve more of your attention.', '“Things which matter most must never be at the mercy of things which matter least.”', '— Johann Wolfgang von Goethe', 'Instead of trying to do everything and not having enough time for the important things in your life, do only what’s important to you, your business or your goals.', 'How To Start Doing Less', 'Imagine you have a workday in which you actually feel relaxed and in control. You only have a few tasks to do, but they’re chosen so that they have the most impact. Instead of being stressed out, you feel focused and productive.', 'The question is, how can you actually make this happen? It almost sounds too good to be true.', 'To do so, you’ll need to (1) become ruthless about eliminating the unimportant and (2) you need to become a master at identifying the truly important stuff.', 'To do so, I suggest you ask yourself a few key questions such as:', '• If I could do only 3 things today, what would it be?', '• What tasks have an impact that lasts beyond this week or this month?', '• What tasks significantly contribute to the progress of achieving my goals?', '• Does this task have a higher return (in terms of value) on my time investment compared to other tasks?', 'These questions will determine the value of your tasks, and you can then decide which tasks are worthy of your time and which ones should be delegated or eliminated.', 'If you focus only on those tasks that give you the biggest return on your time investment, you’ll become a lot more productive while you’re actually doing less. This a complete paradox that requires a shift in thinking, but once you experienced the effects of it yourself, you won’t want to go back to your old way of working.', 'Bonus Tip: Work On Your Priorities In The Morning', 'I recommend that you do your most important tasks always at the start of your day. The reason why is that, early in the day, you’ll still have the resources (such as focus, willpower and energy) available to work on these tasks with the intensity they require.', 'Besides, by working on your most important tasks in the morning, you’ll make sure that they actually get done. When you schedule your most important tasks for later in the day, chances are that they won’t get done. Emergencies come up, other people will make certain demands and other things get in the way of your most important tasks.', 'Therefore, make sure you always tackle your most important tasks in the morning. The rest of the day will feel like a breeze when you’ve done this.', 'Now Do It', 'The objective is to do less, not more, but achieve more because of the choices you make. Don’t fall into the trap of keeping yourself as busy as possible in order to feel good and feel productive. Rather, always focus on simplifying, reducing and eliminating.', 'Keep your focus on that what’s truly important, which are often just a few tasks, activities or projects. That’s how you become highly productive and achieve better results at a faster pace.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/should-you-be-doing-more/qotw0607-2-2/', '2021-06-09T12:00:00Z', '2021-06-09T12:00:00Z'),
  ('l7503', 'to-what-extent-is-the-universe-conceivable', 'gaia', 'name', null, array['Human ‘conception’ of the Universe works like the eyes conceiving of the body. We may be a component of the Universe – a critical one at that – and yet our function is to look outward (like the eyes). We are not designed to understand that which is happening behind the eyes, but to see and sense and bring form and color to the Universal body. We do not understand the inner workings of the Universe and thus cannot fully conceive of it. We can only conceive of our domain, but that should be enough. We must perform our function impeccably.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/to-what-extent-is-the-universe-conceivable/to-what-extent-is-the-universe-conceivable-2/', '2021-06-13T12:00:00Z', '2021-06-13T12:00:00Z'),
  ('l7501', 'to-what-extent-is-the-universe-conceivable', 'b-janszen', 'name', null, array['Understanding the Universe is like being in a boat in the middle of the ocean. In all directions, it appears as though the horizon forms a circle and thus creates a boundary. At the same time, it seems that the horizon continues infinitely in all directions. Yet, amidst all of this, we can fathom that there does exist a distant shore somewhere, and thus we feel at ease somehow. This is how I imagine the Universe as we can observe it. A multidimensional fractal that exists as a reflection of our minds and their limitations.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/to-what-extent-is-the-universe-conceivable/to-what-extent-is-the-universe-conceivable/', '2021-06-13T12:00:00Z', '2021-06-13T12:00:00Z'),
  ('l7497', 'to-what-extent-is-the-universe-conceivable', 'uppsala-university', 'name', null, array['Uppsala University researchers have devised a new model for the Universe — one that may solve the enigma of dark energy. Their new article, published in Physical Review Letters, proposes a new structural concept, including dark energy, for a universe that rides on an expanding bubble in an additional dimension.', 'We have known for the past 20 years that the Universe is expanding at an ever accelerating rate. The explanation is the “dark energy” that permeates it throughout, pushing it to expand. Understanding the nature of this dark energy is one of the paramount enigmas of fundamental physics.', 'It has long been hoped that string theory will provide the answer. According to string theory, all matter consists of tiny, vibrating “stringlike” entities. The theory also requires there to be more spatial dimensions than the three that are already part of everyday knowledge. For 15 years, there have been models in string theory that have been thought to give rise to dark energy. However, these have come in for increasingly harsh criticism, and several researchers are now asserting that none of the models proposed to date are workable.', 'In their article, the scientists propose a new model with dark energy and our Universe riding on an expanding bubble in an extra dimension. The whole Universe is accommodated on the edge of this expanding bubble. All existing matter in the Universe corresponds to the ends of strings that extend out into the extra dimension. The researchers also show that expanding bubbles of this kind can come into existence within the framework of string theory. It is conceivable that there are more bubbles than ours, corresponding to other universes.', 'The Uppsala scientists’ model provides a new, different picture of the creation and future fate of the Universe, while it may also pave the way for methods of testing string theory.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/to-what-extent-is-the-universe-conceivable/qotw0613-2-2/', '2021-06-13T12:00:00Z', '2021-06-13T12:00:00Z'),
  ('l7493', 'to-what-extent-is-the-universe-conceivable', 'gilead-a', 'name', null, array['One idea explains all the weird coincidences in the universe.', 'PHYSICISTS dislike coincidences such as those set out on these pages, suspecting them of covering up some new principle they don’t yet grasp. But when they run out of theories, there’s a one-size-fits-all explanation that can answer everything without really answering much at all: the universe is as it is because we’re here to see it. This piece of circular logic is the anthropic principle. A universe inhospitable to life would have no human beings around to observe it, so the one we see must, by definition, possess features essential to accommodating intelligent life. But that doesn’t tell us whether a slightly different universe might still host life, why our particular universe exists and not some other, or why we see finely balanced features with no bearing on the emergence of life.', 'And yet there is an idea that sweeps all these objections away: all conceivable universes exist side by side in a patchwork multiverse. We merely inhabit one out of the infinite selection.', 'Our cosmos’s five most startling coincidences – and what lies behind them', 'Why believe in the multiverse? Because a process such as inflation (see “The universe is flat as a pancake. Coincidence?“), if left unchecked, could produce a multitude of causally disconnected universes. String theory, still most physicists’ favoured route to an overarching theory of everything, conjures up an entire landscape of maybe 10100 or more universes, all with slightly varying properties.', 'But some still see the multiverse as an abdication of scientific responsibility: a fancier way of simply saying “coincidences happen”. And, if true, it means some astronomers out there are forced to justify a universe even more replete with coincidences than ours, while others could be bored stiff in a completely random cosmos.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/to-what-extent-is-the-universe-conceivable/qotw0613-2/', '2021-06-13T12:00:00Z', '2021-06-13T12:00:00Z'),
  ('l7556', 'how-long-will-you-be-remembered-after-you-die', 'denmark-guy', 'name', null, array['I remember when my mother died, some years back, I went to a local park and spent several hours there. I sat on a bench and just looked around at world… and was struck by the fact that this HUGE event had just happened: My Mother Died. The only living direct relative of mine had passed away, and I was essentially alone in the world. I have no brothers and sisters, you see, and my parents are both dead. Although I am basically “dad” to three wonderful (now adult) children, they are not mine in the biological sense… they are ultimately my wife’s, through her previous marriage.', 'Everyone Around You Will be DEAD in 100 Years', 'Near Snoqualmie Pass, WA', 'I don’t mean for this to sound like a downer post, but if you look around you where you are right now, odds are that every single person can seefrom wherever you are will be dead, 100 years from now.', 'Anyway, I sat in that park and watched the world go about its business, and I realized that in spite of the fact that a monumental even was happening to ME, nobody elseknew or cared.', 'Thinking forward to today, that also made me realize that when I die, pretty much nobody will notice. When I die, the last person with a clear memory of my mother will be gone. Will anyone have a clear memory of me, after I die? After a year? Five years? Ten years?', 'Then again, does it matter?', 'Some people are more attached than others to leaving a “legacy” behind for others to remember them by. Me? Not so much. Although it does amuse me — at least on some minimal level — that these words we write here will supposedly be recorded on the blockchain forever.', '“Forever” is a long time, mind you.', 'I don’t know what people will remember. But then again, I never put much effort into doing anything worth “being remembered FOR.”', 'What Matters… and What Doesn’t', 'The great thing about us humans is that we are really vastly different.', 'Bird taking a rest… on a bird', 'There’s a lot of jargon circulating about how we are “all the same,” but really? Such a range of differentthings matter to us. Including… death.', 'I don’t think much about death; it’ll come soon enough, and I’m quite content with the idea of “whatever happens” coming as a surprise. And maybe that’s why I’m really more concerned with what happens while I am here than after I am gone.', 'That was one of the things my mother and I did not share: She pretty much started “planning her death” when she was in her 50’s and then got to spend another 30 years “putting her papers in order.“', 'It’s funny, after 8 1/2 years, it’s getting harder and harder to remember her. That’s what the human mind does, over time. The daily stuff fades, and only a few highlights remain…']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/how-long-will-you-be-remembered-after-you-die/qotw0620-2-3/', '2021-07-06T12:00:00Z', '2021-07-06T12:00:00Z'),
  ('l7552', 'how-long-will-you-be-remembered-after-you-die', 'harry-s', 'name', null, array['One of the things that always surprises me is the desire to be remembered. There are so many people who want to be remembered for something or other so that when they die it will somehow make a difference. Most of these people are just ordinary people and I think it is enough to have lived a full life without imposing their stupidities on future generations. Once you are dead, this life then ends and another may begin. It may be that they are so afraid of what comes after death that is too frightening to contemplate, and in desperation they want to leave a mark of themselves behind.', 'I think about the palaces and mosques, the fortifications and defences built by great leaders who may themselves have had dreamt of greatness. And we can see their constructions all over central Asia, standing proud and distinct in the otherwise desert like terrain. But who really remembers them and how much do they remember? Even if someone’s name is remembered, what does that really signify?', 'Really, who cares? Think about other people who are ‘famous’. We know very little about them as people; were they nice people, did they like life, what were their likes and dislikes, what did their children think of them, etc? Even if we can understand them as people, I ask again, who cares?', 'So, if we don’t care about great people in history, who is going to care about lesser achievers like an actor, the owner of a string of supermarkets, a hockey player, or a politician? In fact, people are hardly remembered when they are alive never mind years after their death. People who try to be remembered are just wasting their time. Instead of trying for material greatness, isn’t it better to just try to become a better person themselves? It must be worth more to just look inside and find out how they can be better whilst they are alive, to live better, help others, and be happy with their life as it is.', 'So, we are left, in country after country with buildings, beautiful in themselves, that are a minimal reminder that others have been here before. Where are they now; skeletons of empires, scattered in the desert!']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/how-long-will-you-be-remembered-after-you-die/qotw0620-2-2/', '2021-07-06T12:00:00Z', '2021-07-06T12:00:00Z'),
  ('l7547', 'how-long-will-you-be-remembered-after-you-die', 'victor-p', 'name', null, array['Realistically, as long as the last person that remembers you will live. In the present day, assuming they’re 10 years old and remember you for the entirety of their lives while having the rough maximum possible lifespan (125 years), the last real memory of you will die in 115 years. If you live for another, say, 70 years, and make an impression on a 10-year-old on your very last day, it could be 185 years.', 'Think about the big names in history. Conquerors, dictators, artists, inventors, activists. In the case of those that died over a hundred years ago, it’s (almost) safe to say that nobody alive has ever met them in person.', 'Nobody has shared a beer, a late-night story, a good joke or a hardship with them. Nobody was there to see them fuss over their worries or cower in fear during lower points of their lives. Nobody came to give them the pep talk they needed, mentored them when they needed to grow, or learned great wisdom from the example of their actions.', 'The impact of their work is well-known, but this builds an idea of a person rather than presenting an authentic person per se.', 'In some cases, these great historical figures left behind diaries, such as in the case of Marcus Aurelius. They are the closest thing to a retelling of an internal monologue one can have, but even that is a rendition of the man, not the man himself.', 'With the rate tech is evolving now, future generations should be able to watch present-day content as if no time had passed, allowing for whatever ways you present yourself to survive the passage of time unscathed. But by the same coin as with ancient diaries, I think they fall short of presenting the true person.', 'Carpe diem, then. Your memory may become an abstract notion – if it survives at all – but the effects of your actions may ripple throughout the years.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/how-long-will-you-be-remembered-after-you-die/qotw0620-2/', '2021-07-06T12:00:00Z', '2021-07-06T12:00:00Z'),
  ('l7545', 'who-wins-between-good-and-evil', 'j-dizzle', 'name', null, array['This is a trick question, as the ‘battle’ between ‘good’ and ‘evil’ is the creative tension of existence itself. They pull on each other, push on each other, dance together, fall in love, go to war, forget each other, and yet they are always two sides of one coin. ‘Good’ and ‘evil’ are the building blocks of all form, all mind, all life, all consciousness. It is the light and dark that casts shadows upon the stage to enrich the play. For us humans, the notions of ‘good’ and ‘evil’ are simply ways to comprehend and dualize our conscious experience. We cling to one as opposed to the other, simply out of the ignorance of seeing their mutual implications. This is just part of the human condition. Is the sun ‘good’ and the ‘rain’ evil? Is the elephant ‘good’ and the hyena ‘evil’? Perhaps in these examples, we can reason why each is simply doing what it does. These are, at their deepest levels, mutualistic relationships – going beyond ‘good’ and ‘evil’ altogether.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/who-wins-between-good-and-evil/who-wins-between-good-and-evil/', '2021-07-06T12:00:00Z', '2021-07-06T12:00:00Z'),
  ('l7542', 'who-wins-between-good-and-evil', 'greg-h', 'name', null, array['Tolkien was clear in the stories of The Silmarillion and The Lord of the Rings that the struggle between good and evil is never-ending. No sooner did the Valar vanquish Melkor than Sauron emerged in Middle-earth and forged the Rings of Power to bring it all under his control. If history in the first Three Ages are any indication, one can assume that no sooner do the heroes of The Lord of the Rings vanquish Sauron at the end of the Third Age than a new, perhaps worse promoter of evil will arise in the Fourth Age (though Tolkien gives no indication of this in his brief chronology of the Fourth Age).', 'Not only do the seeds of evil continue to sprout and grow in Middle-earth, but the dark conditions in which they flourish continue to spread. As the sources of light diminish over the different Ages of Middle-earth, it becomes easier to deny the power of light and tout that of darkness. This expansion has fostered a loss of hope and a lack of faith that helped defeat the various Elven kingdoms in Beleriand, and later Númenor. After that, it sapped the strength from the exiled kingdoms of Arnor and Gondor.', 'In our world, a feeling of growing darkness can give rise to ennui and defeatism. Inherent in this defeatism is the sense that evil is stronger and somehow more real than goodness. This is, of course, the precise opposite of the truth as many, including Tolkien, see it: Evil cannot prevail over goodness because evil is just a denial of the only true and fundamental wisdom: God, in the Judeo-Christian and Islamic vocabulary; Enlightenment in the Buddhist.', 'In other words, the light may be hidden or blocked, thereby allowing darkness to grow, but it cannot be destroyed. All you have to do to regain the light is remove whatever obscures it, be it Melkor’s or Sauron’s evil. The great thing is that the moment you remove whatever blocks the light, it immediately flows again, illuminating the world as brightly as before.', 'Of course, as The Lord of the Rings so aptly points out, removing the obstacles to the light is often very difficult and comes at a very high price. More importantly, even though the light returns as strong as before once the obstacles are removed, the damage caused by their evil lingers, sometimes long after.', 'Shadows of evil', 'Tolkien often used the word shadow in relation to evil and evil characters, even going so far as to refer to Sauron as the Shadow. As the darkness created by an object blocking out light, a shadow lacks substance. Shadow can also mean a faint representation, in the sense of “he is only a shadow of his former self.” And shadow can refer to darkness and gloom, as when Aragorn tells Celeborn and Galadriel that Gandalf has fallen “into shadow” in Moria.', 'Tolkien’s calling Sauron the Shadow is an effective way of getting across his dark, evil aspect while reinforcing the insubstantiality of his evil. Same goes for Sauron’s good buddies, the Ringwraiths, or Nazgûl. The Ringwraiths, too, are just dark shapes that instill great fear, even though they seem to lack any substance. Consider that when Merry stabs the Lord of the Nazgûl, his hauberk (coat of mail) gives the only indication of where to try to wound him.', 'The threat of becoming a shadow like one of the Ringwraiths or Sauron himself is one that particularly menaces Frodo as the bearer of the One Ring. After the Lord of the Nazgûl wounds Frodo with the Morgul-knife, Gandalf notices that Frodo is becoming slightly transparent. As the Ring’s evil power becomes stronger as Frodo nears Mordor, this process of turning into a wraith becomes more pronounced — Frodo is literally becoming a shadow.', 'In Frodo’s struggle against turning into a wraith, Tolkien illustrates one process of becoming evil (metaphorically descending into shadow). It is not a process that happens all at once — it progresses gradually over time, like Frodo’s very gradual fading. Some critics suggest that Frodo’s initial disgust toward Gollum — his criticism of Bilbo’s pity towards him, and his revulsion at the idea that Gollum is at heart a hobbit — are due to Frodo’s fear of what he could become. In this view, the evil that Frodo carries can separate him from his own self and all he holds dear. In the end, the power of Ring, especially given Frodo’s continued use of it, corrupts him and convinces him that he can stand against Sauron and be the new Lord of the Ring.', 'Tolkien’s notion of “wraithing,” that is, gradually giving yourself over to a controlling power until you’re just a shadow of your former self, helpless before the evil influence, is very compelling and particularly applicable to modern life. Note that the power causing the “wraithing” doesn’t have to be as symbolic as the Ring: it can be any of the thousand-and-one addicting influences that rob people of their humanity. The key idea here seems to be that this process of becoming evil renders all of its “wraiths” into indistinguishable shadows, robbing them of individuality and personality.', 'Tolkien and the last battle against evil', 'In the Norse mythology that so influenced Tolkien’s writings, the final battle that ends the world is called Ragnarok, the Doom of the Gods (or Twilight of the Gods). This great conflagration not only destroys the Norse gods of the higher realm of Asgard, such as Odin and Thor, but also ends up destroying all of Midgard (our world of “Middle-earth”) as well. But from the ashes of this final battle, a new, more beautiful world eventually rises.', 'Ragnarok is quite unlike the Christian notion of Armageddon in the Book of Revelation. There, the angels of God overwhelm and cast down the Devil and his beasts just before God creates a new heaven and earth — it’s not even a fair fight. In Ragnarok, the gods face giants and other fell beasts knowing they will be killed in the process. In other words, the Norse gods face the Last Battle as any Viking hero would: ready and happy to die if necessary. In this Norse version of the end of the world, both good (the forces of world order) and evil (the forces of chaos) annihilate each other. The few survivors establish the new world.', 'Despite Tolkien’s firm personal belief in a Day of Judgment, though, his fantasy works show no such certainty, only hinting at the possibility of a Last Battle and a new world to follow. His clearest reference is in the Dwarves’ belief that at death they will wait in the Halls of Mandos until the Last Battle, at which time they will come out and help their father Aulë fashion a new world. Other than that suggestion, Tolkien gives only vague references to a day when the world is changed or made anew.', 'But you can imagine that if pushed to depict the Last Battle in Middle-earth, he would fashion something closer to Ragnarok than Armageddon. This assumption is based on the way in which Gandalf and Aragorn face the Battle of Morannon (“Black Gate”) near the end of The Lord of the Rings. Here, they decide to face the Enemy and his great forces right outside the Black Gate of Mordor — not from any naive notions of victory but to buy necessary time for Frodo to destroy the Ring in the fires of Mount Doom.', 'They know full well that the chances of Frodo succeeding are remote, and that even if he does they may not live long enough to see it. Nevertheless, like the Norse gods at Ragnarok, they’re ready to battle the enemy in the face of almost certain defeat. The biggest difference between the heroes of the Battle of Morannon and those of Ragnarok is that Aragorn and the others show none of the good old Norse Gods’ relish for the fight and little of the Rohirrim’s delight in a warrior’s death.', 'Rather, the warriors of the Battle of Morannon seem quite resigned to their fate. They face this tremendous challenge with all the fear and trepidation of modern, non-professional soldiers. In fact, Tolkien’s attitude in The Lord of the Rings towards war and battling evil is very contemporary. In most of the battles, good guys are far outnumbered by bad guys, and their chances of victory are usually slim to none. Ignoring for the moment the adolescent battle banter between Gimli and Legolas, Tolkien’s warriors are serious about their jobs, especially Gandalf and Aragorn. The only exceptions seem to be the Théoden and the Rohirrim.', 'Tolkien’s attitudes toward warfare in The Lord of the Rings closely resembles the outlook prevailing since World War I: War is hell, the world is a dangerous place, and the forces of evil are everywhere and numerous. Just as fewer of us are certain that good always triumphs over evil, heroes such as Gandalf and Aragorn are far from certain about the success of their desperate venture to prevent Sauron’s total domination of Middle-earth.', 'Tolkien’s heroes fight with little assurance of victory in their particular struggle, to say nothing of a final triumph of good over evil in a much later Last Battle. They fight knowing that they must resist evil to preserve the islands of light in Middle-earth and to arrest the spread of darkness, even with no guarantee of success. In them, you can see a blend of Viking courage with a lot of 20th-century ambiguity over the final outcome of the good/evil question.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/who-wins-between-good-and-evil/qotw0704-2-2/', '2021-07-06T12:00:00Z', '2021-07-06T12:00:00Z'),
  ('l7538', 'who-wins-between-good-and-evil', 'johnny-l', 'name', null, array['I believe that the battle only exists within ourselves. And the whole outcome of that battle is only our soul and our own future. What’s at stake is not the future of the Universe, but whether our soul gets scrapped because we have proven ourselves to be spiritually worthless or used for something greater in our future because we have proven that we can serve usefully. I believe the Universe is not set up in such a way that our vote is the required input to determine it’s future. Such a system would be doomed to failure and be inherently unworkable because we are inherently evil, the expected outcome is for most humans to cast their vote for evil (unknowingly).', 'I believe there is no cosmic battle between good and evil, good does not fight evil, the second it does, it sinks down to evil’s level and becomes evil. So the nature of good isn’t to fight evil or to fight at all, the closest good comes to fighting anything is its own temptations. To fight is inherently self-based. There is no fighting others if you don’t need to defend your SELF. But fighting temptation is only a metaphor of fight, there is no fight when you fight temptation, you are just reworking yourself inside. Fighting is one self fighting another self, to an outside observer, they are both equally self-obsessed. Fighting makes everyone roll in the mud. The good always lose when they roll in the mud. Do not cast pearls before swine, let the pigs stay in the mud without you or your pearls.', 'Furthermore, if the creator of all this is pure good, then evil has no intrinsic validity but is just a blight/cancer on the design, which can be eliminated with just an afterthought if the need arises. Evil doesn’t need to exist, good and evil is not a yin yang dichotomy. Evil is just a cancer on good, parasiting off good. The body does not need the cancer or the parasite to exist. The odds were always asymptotically 100% stacked on the side of the good, evil never had a 50% chance. Those who have proven themselves wheat will be automatically protected from the abuses of the evil and be given immense power to serve and to protect themselves effortlessly, but only after death. The creator merely tolerates evil simply to continue harvesting the few good souls that somehow manage to emerge from the cesspool that we call humanity. Humanity is overall a bad crop. We are a garden of tares with a few wheat mixed in.', 'So evil is tolerated for the sake of harvesting the very few wheat. But down here, from our perspective, we get all macho and stuff and believe there is a cosmic battle going on between good and evil, and our critical input is needed because we get to awesomely determine the future of the Universe. Such is our conceit. Our self-importance infects everything, corrupts everything, defiles everything, it spreads like cancer on every idea. Every idea eventually is tainted with our need to feel awesome about ourselves. It’s like a bad 80’s action movie. Every single idea humanity has is like a bad movie script where the theme of everything is that the hero wins in the end by kicking baddie ass and saves the world, funnily this happens to be how an evil mind works, because it reeks of self-worship. The world doesn’t need us. What we need is to behave. That’s all that’s needed from us, not bombastic martyrdom or playing God, we just need to prove ourselves worthy servants, not some hotshot intern who’s gonna revolutionise the workplace and invent the next iPhone.', 'The apocalypse is irrelevant. Every individual encounters his personal apocalypse upon his death. Judgement day happens one death at a time. Lots of humans dying simultaneously doesn’t change the way the system is designed. Repentance happens as soon as you can help it, the world is not hanging on your repentance, you are not that important to the overall scheme of things if you are evil and therefore spiritually worthless.', 'There is nothing to be done about it in terms of saving the world, or eliminating poverty or world hunger or eradicating malaria. These are all emanations of people who like to gaze at the mirror at their own reflections or fantasise about someday becoming super awesome by doing undeniably awesome stuff.', 'All that is to be done is to work on becoming good if you are evil, or becoming even more good if you are already good.', 'The joke was always on us. We never mattered to anyone except ourselves. We get to save ourselves, the world was always out of our hands, just like the soul of the next person standing beside us is also out of our hands. Just observe the nature of reality, if you cannot even change another person’s mind, how could you save or truly affect anything other than yourself?', 'Bombast less, repent more.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/who-wins-between-good-and-evil/qotw0704-2/', '2021-07-06T12:00:00Z', '2021-07-06T12:00:00Z'),
  ('l7581', 'why-is-there-so-much-homelessness-in-the-usa', 'cnscsns', 'name', null, array['Statistically speaking, there is no good reason for the continuation of homelessness in the USA (at least for those who would rather not be homeless). It is estimated to cost $25 billion to eradicate homelessness in this country. For perspective, that is less money than our nation spends on Christmas decorations each year. Likewise, it costs on average 30 to 40 thousand dollars per homeless person per year when we factor in medical bills, shelters, jail and court fees, and other expenses. That is estimated to be 3-4 times more than it would likely cost to house these people – about $10,000. So there is no clear economic benefit to our system as it is, and incentive to change the system. So why don’t we?', 'My theory is that by intentionally allowing for a modern-day ‘untouchable’ class – one that is on the streets, in our faces all the time – a message is sent to the American public that danger looms should we step off the modern-American treadmill. We dare not risk becoming one of ‘those’ people who loses everything and is thus shunned and subservient in society. It’s strictly a psychological message to keep the sheep in line, to incite fear, and to maintain a power-dynamic in which the majority is at the whim of those atop the pyramid.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/why-is-there-so-much-homelessness-in-the-usa/why-is-there-so-much-homelessness-in-the-usa/', '2021-07-12T12:00:00Z', '2021-07-12T12:00:00Z'),
  ('l7577', 'why-is-there-so-much-homelessness-in-the-usa', 'rick-g', 'name', null, array['The short answer is that people in the lower two thirds of income level are making less money than they did 25 years ago. They can’t afford housing. The USA as a whole is getting poorer, while people in the uppermost five percent of income are getting richer and richer.', 'There are two reasons for why we have gotten poorer:', '• One is nobody’s fault.', '• The other reason is the fault of the Republican Party since the Reagan Administration.', 'Reason One:', 'The world economic system has changed; this is nobody’s fault. At the end of WWII in 1945, the USA was the only country with factories and infrastructure. We had full employment and sold our products all over the world. Millions of veterans were sent to universities and trade schools at government expense. Interstate Highways, power plants and public schools were built with US and state taxes, which were higher and more fair then they are today.', 'However, during the next sixty years, the rest of the world recovered from WWII and caught up with us. They built their own factories and laboratories and infrastructure (largely by buying it from us). Now they make and sell the same stuff we do, often cheaper. This means that factories have closed in the USA, and millions of manufacturing jobs have been lost.', 'Also, during that sixty years, computers have come into use. Millions of people who used to answer telephones, make appointments, and file records, in other words, the people who did the paperwork — their jobs no longer exist.', 'These people had to take low wage jobs. They can’t earn enough to save for emergencies, they’re getting older and sicker. One little car breakdown or illness, and they and their families are out on the street. Poverty and distress also generate drug problems and crime.', 'Another nobody’s-fault reason why we’re poorer today is that the population of the USA has more than doubled since I was in high school. Twice as many people are trying to live on the same amount of land and resources. Real prices have gone up, while real wages have gone down.', 'All of these problems could be alleviated by intelligent government. But we haven’t had that.', 'Reason Two:', 'Since 1981, when Ronald Reagan was put up for President, the Republican Party has slowly taken over Congress and most local governments.', 'The Republican Party is owned and operated by the billionaire class in the USA, people like the Koch Brothers and the Sackler Family. They want to pay lower taxes.', 'The Republican Party tells the voters that the solution for all of America’s problems is for rich people to have more money.', 'By endless cheap patriotism, waving the flag, talking about crime, drugs, prayer in schools, immigrants, lowlife behaviour, making us envy celebrities, saying “they” are going to take away our guns, that we don’t need education, our military is weak, etc., they have fooled poor uneducated people into believing that the solution for all of America’s problems is for rich people to have more money.', 'Since 1981, the Republicans also have changed many laws so they can now do things on the stock market and with the banks and during political campaigns that were illegal before 1981.', 'This is what the Republicans have done instead of working on America’s economic and social problems.', 'Meanwhile, the Democrats either have been letting it happen, or been unable to do anything because the Republicans control the Congress.', 'Meanwhile, our bridges and roads are wearing out, cities are deserted, schools get no funding. we lose our leadership in technology, wages are so low that our economy fails to provide housing, medical care, or even enough food for millions of citizens.', 'It’s time for citizens to wake up. Racism, religion, ignorance, and simple-minded patriotism won’t cut it. We need a political revolution.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/why-is-there-so-much-homelessness-in-the-usa/qotw0711-2-2/', '2021-07-12T12:00:00Z', '2021-07-12T12:00:00Z'),
  ('s1', 'what-do-you-owe-the-version-of-yourself-you-were-ten-years-ago', 'quarx', 'username', 'Not obedience — but an honest answer to the questions they were too young to resolve.', array['The person you were ten years ago made promises on your behalf: to become something, to never become something else. It is tempting to treat those promises as contracts. But that younger self lacked information you now have, and holding yourself to their plans can be a quiet form of tyranny.', 'What you do owe them is attention. They carried hopes that were not foolish, only unfinished. The debt is to look at each of those hopes honestly and either pursue it, or set it down deliberately — with a reason they would understand. Abandoning a dream by drift is the only real betrayal.']::text[], 'If it turned out that people who keep their early commitments are consistently happier than people who revise them, I would weigh loyalty much more heavily.', 'live', false, true, false, null, '2026-11-16T12:00:00Z', '2026-11-16T12:00:00Z'),
  ('s2', 'can-you-love-someone-you-do-not-like', 'quarx', 'username', 'Yes — liking is about compatibility; love is about commitment to someone’s good.', array['Liking is a response: someone’s humor, habits and company please us. Love, at its deepest, is a stance: wanting another person to flourish, and being willing to act on it even when it costs us.', 'Families prove this constantly. Many people love a parent or sibling whose company they find exhausting. The dislike is real, and so is the love. If anything, love that survives dislike may be the purest kind, because it is not being paid for by pleasure.']::text[], 'If love without liking always curdled into resentment over time, I would say what we call love there is really duty.', 'live', false, true, false, null, '2026-11-15T12:00:00Z', '2026-11-15T12:00:00Z'),
  ('s3', 'if-ai-can-write-theories-what-is-human-thought-for', 'quarx', 'username', 'Thinking was never only about producing answers; it is how a person becomes someone.', array['A machine can generate a theory about grief. It cannot grieve. When you work out what you believe about death, you are not just producing a text — you are rearranging yourself, deciding what to fear and what to accept.', 'So the value of human thought shifts from the output to the thinker. We will read machine-written ideas the way we read encyclopedias. But the theories that move us will be the ones where we can feel a life behind the words — someone who had something at stake.']::text[], 'If people turned out to be equally moved by theories once they learned a machine wrote them, I would have to admit the "life behind the words" matters less than I think.', 'live', false, true, false, null, '2026-11-14T12:00:00Z', '2026-11-14T12:00:00Z')
on conflict (id) do nothing;
